def superset_auth_check_token_validity(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_auth_check_token_validity"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, superset_instance_id=None, auth_session_id=None, error_code=None, error_message=None):
        # observable dynamics: always record if a logs collection exists (or create request_logs.json)
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": superset_instance_id,
            "auth_session_id": auth_session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(fname, logs)

    # simple global rate limit: 120/min across this service (best-effort)
    logs = _load("request_logs.json")
    if isinstance(logs, list) and logs:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-4000:]:
            ts = _parse_dt((r or {}).get("timestamp") or (r or {}).get("created_at"))
            if ts and ts.replace(tzinfo=None) >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="global_120_per_min")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit="120/min")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    if not isinstance(instances, list) or not isinstance(sessions, list):
        _log("error", error_code="CONFLICT", error_message="Datastore unavailable")
        return _err("CONFLICT", "Failed to read datastore.")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance configured.")

    # deterministically choose an active instance, but MUST pick one that has a usable session
    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))

    chosen_inst = None
    chosen_sess = None
    for inst in active_instances:
        iid = inst.get("id")
        if not iid:
            continue
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == iid and s.get("access_token")]
        if not cand:
            continue
        # prefer authenticated; otherwise any token-carrying session
        cand.sort(key=lambda s: (
            0 if s.get("status") == "authenticated" else 1,
            _parse_dt(s.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc),
            s.get("id") or ""
        ))
        chosen_inst = inst
        chosen_sess = cand[0]
        break

    if not chosen_inst or not chosen_sess:
        _log("error", error_code="UNAUTHORIZED", error_message="No Superset access token available to validate")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    # Offline simulation of /api/v1/me:
    # - treat sessions with status authenticated as valid
    # - expired/revoked/anonymous/error treated as invalid (401/403 style)
    # Business rule: update last_validated_at and last_validation_ok; on 401/403 mark expired (or revoked if explicitly indicated)
    sess_id = chosen_sess.get("id")
    idx = None
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == sess_id:
            idx = i
            break
    if idx is None:
        _log("error", superset_instance_id=chosen_inst.get("id"), auth_session_id=sess_id, error_code="NOT_FOUND", error_message="Auth session disappeared")
        return _err("NOT_FOUND", "Auth session not found.", id=sess_id)

    st = (sessions[idx].get("status") or "anonymous")
    now = _now_iso()
    sessions[idx]["last_validated_at"] = now

    invalid = st in ("anonymous", "expired", "revoked", "error")
    # if there are recorded last_error_code of 401/403, treat as invalid too
    last_err_code = sessions[idx].get("last_error_code")
    if last_err_code in ("401", "403"):
        invalid = True

    if invalid:
        sessions[idx]["last_validation_ok"] = False
        # choose revoked if session already revoked, else expired
        if st != "revoked":
            # legal transitions enforced
            allowed = {
                "anonymous": ("authenticated", "error"),
                "authenticated": ("expired", "revoked", "error"),
                "expired": ("authenticated", "revoked", "error"),
                "revoked": ("authenticated",),
                "error": ("anonymous", "authenticated"),
            }
            cur = st
            target = "expired"
            if target in allowed.get(cur, ()):
                sessions[idx]["status"] = target
            elif cur == "expired":
                sessions[idx]["status"] = "expired"
            # clear expiry if unknown (best-effort)
        sessions[idx]["access_token_expires_at"] = None
        sessions[idx]["updated_at"] = now
        _save("auth_sessions.json", sessions)

        _log("ok", superset_instance_id=chosen_inst.get("id"), auth_session_id=sess_id)
        return {
            "valid": False,
            "superset_instance_id": chosen_inst.get("id"),
            "auth_session_id": sess_id,
            "checked_at": now,
            "error": {"code": "401", "message": "Access token invalid or expired"}
        }

    sessions[idx]["last_validation_ok"] = True
    sessions[idx]["last_error_code"] = None
    sessions[idx]["last_error_message"] = None
    sessions[idx]["updated_at"] = now
    _save("auth_sessions.json", sessions)

    _log("ok", superset_instance_id=chosen_inst.get("id"), auth_session_id=sess_id)
    return {
        "valid": True,
        "superset_instance_id": chosen_inst.get("id"),
        "auth_session_id": sess_id,
        "checked_at": now
    }

def superset_auth_refresh_token(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
    except Exception as e:
        return _err("CONFLICT", "Failed to read datastore.", details=str(e))

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance configured.")

    def _dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    active_instances.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
    inst = active_instances[0]

    # Need a session with refresh_token present
    candidate_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst.get("id") and s.get("refresh_token")]
    if not candidate_sessions:
        return _err("INVALID_TRANSITION", "Cannot refresh token: no refresh_token present for any session on the active instance.")

    # Prefer most recently updated authenticated sessions
    def _score(s):
        st = s.get("status")
        return (0 if st == "authenticated" else 1, -(int((_dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.now(datetime.timezone.utc)).timestamp())), s.get("id") or "")
    candidate_sessions.sort(key=_score)
    sess = candidate_sessions[0]

    # Offline simulated refresh: rotate access_token; optionally rotate refresh_token
    new_access = "access_" + uuid.uuid4().hex
    rotate_refresh = True
    new_refresh = ("refresh_" + uuid.uuid4().hex) if rotate_refresh else sess.get("refresh_token")

    # Update session with lifecycle rules: must become authenticated
    transitions = {
        "anonymous": ["authenticated", "error"],
        "authenticated": ["expired", "revoked", "error"],
        "expired": ["authenticated", "revoked", "error"],
        "revoked": ["authenticated"],
        "error": ["anonymous", "authenticated"],
    }
    cur = sess.get("status")
    if cur != "authenticated" and not (cur in transitions and "authenticated" in transitions[cur]):
        return _err("INVALID_TRANSITION", f"Cannot transition auth session from '{cur}' to 'authenticated' via refresh.", session_id=sess.get("id"))

    updated = False
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sess.get("id"):
            ns = dict(s)
            ns["access_token"] = new_access
            ns["refresh_token"] = new_refresh
            ns["token_type"] = "bearer"
            ns["status"] = "authenticated"
            ns["last_error_code"] = None
            ns["last_error_message"] = None
            ns["last_validation_ok"] = True
            ns["last_validated_at"] = now
            # Best-effort expiry: 1 hour from now
            exp = (datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(hours=1)).isoformat() + "Z"
            ns["access_token_expires_at"] = exp
            ns["updated_at"] = now
            sessions[i] = ns
            updated = True
            break

    if not updated:
        return _err("NOT_FOUND", "Auth session not found for refresh.", session_id=sess.get("id"))

    try:
        _save("auth_sessions.json", sessions)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist refreshed token.", details=str(e))

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "superset_instance_id": inst.get("id"),
        "session_id": sess.get("id"),
        "token_type": "bearer",
        "access_token": new_access,
        "refresh_token": new_refresh,
        "access_token_expires_at": exp,
        "refreshed_at": now,
        "latency_ms": latency_ms
    }

def superset_auth_authenticate_user(username=None, password=None, refresh=True, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if username is not None and not isinstance(username, str):
        return _err("VALIDATION_ERROR", "username must be a string or null.")
    if password is not None and not isinstance(password, str):
        return _err("VALIDATION_ERROR", "password must be a string or null.")
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")

    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
    except Exception as e:
        return _err("CONFLICT", "Failed to read datastore.", details=str(e))

    def _dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance configured.")
    active_instances.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Find best existing session for this instance (prefer username match if provided)
    inst_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id]
    if username is not None:
        inst_sessions_user = [s for s in inst_sessions if s.get("username") == username]
        if inst_sessions_user:
            inst_sessions = inst_sessions_user

    def _score(s):
        st = s.get("status")
        has_token = bool(s.get("access_token"))
        return (0 if (st == "authenticated" and has_token) else 1 if has_token else 2,
                -int((_dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.now(datetime.timezone.utc)).timestamp()),
                s.get("id") or "")
    inst_sessions.sort(key=_score)
    sess = inst_sessions[0] if inst_sessions else None

    # Helper: validate existing token (offline simulation)
    def _token_valid(s):
        if not s or not s.get("access_token"):
            return False
        st = s.get("status")
        if st in ("anonymous", "expired", "revoked", "error"):
            return False
        exp = _dt(s.get("access_token_expires_at"))
        if exp and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        return True

    # If refresh=true attempt validate -> refresh -> login
    if refresh and sess and _token_valid(sess):
        # Update validation stamps, keep authenticated
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == sess.get("id"):
                ns = dict(s)
                ns["last_validated_at"] = now
                ns["last_validation_ok"] = True
                ns["last_error_code"] = None
                ns["last_error_message"] = None
                if ns.get("status") != "authenticated":
                    # best-effort transition if legal
                    transitions = {
                        "anonymous": ["authenticated", "error"],
                        "authenticated": ["expired", "revoked", "error"],
                        "expired": ["authenticated", "revoked", "error"],
                        "revoked": ["authenticated"],
                        "error": ["anonymous", "authenticated"],
                    }
                    cur = ns.get("status")
                    if cur in transitions and "authenticated" in transitions[cur]:
                        ns["status"] = "authenticated"
                ns["updated_at"] = now
                sessions[i] = ns
                sess = ns
                break
        try:
            _save("auth_sessions.json", sessions)
        except Exception as e:
            return _err("CONFLICT", "Failed to persist session validation.", details=str(e))
        return {
            "superset_instance_id": inst_id,
            "session_id": sess.get("id"),
            "token_type": sess.get("token_type"),
            "access_token": sess.get("access_token"),
            "refresh_token": sess.get("refresh_token"),
            "access_token_expires_at": sess.get("access_token_expires_at"),
            "authenticated_via": "existing_token",
            "authenticated_at": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # If token exists but invalid, mark validation attempt and expire, then try refresh if allowed and refresh_token present
    if refresh and sess and sess.get("access_token") and not _token_valid(sess):
        # Update invalid validation info
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == sess.get("id"):
                ns = dict(s)
                ns["last_validated_at"] = now
                ns["last_validation_ok"] = False
                ns["last_error_code"] = "401"
                ns["last_error_message"] = "Unauthorized"
                # transition to expired if legal
                transitions = {
                    "anonymous": ["authenticated", "error"],
                    "authenticated": ["expired", "revoked", "error"],
                    "expired": ["authenticated", "revoked", "error"],
                    "revoked": ["authenticated"],
                    "error": ["anonymous", "authenticated"],
                }
                cur = ns.get("status")
                if cur != "expired":
                    if cur in transitions and "expired" in transitions[cur]:
                        ns["status"] = "expired"
                    else:
                        ns["status"] = "error"
                ns["access_token_expires_at"] = None
                ns["updated_at"] = now
                sessions[i] = ns
                sess = ns
                break
        try:
            _save("auth_sessions.json", sessions)
        except Exception as e:
            return _err("CONFLICT", "Failed to persist session invalidation.", details=str(e))

        if sess.get("refresh_token"):
            # Perform refresh (simulate)
            new_access = "access_" + uuid.uuid4().hex
            new_refresh = "refresh_" + uuid.uuid4().hex
            exp = (datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(hours=1)).isoformat() + "Z"
            transitions = {
                "anonymous": ["authenticated", "error"],
                "authenticated": ["expired", "revoked", "error"],
                "expired": ["authenticated", "revoked", "error"],
                "revoked": ["authenticated"],
                "error": ["anonymous", "authenticated"],
            }
            cur = sess.get("status")
            if cur != "authenticated" and not (cur in transitions and "authenticated" in transitions[cur]):
                return _err("INVALID_TRANSITION", f"Cannot transition auth session from '{cur}' to 'authenticated' via refresh.", session_id=sess.get("id"))
            for i, s in enumerate(sessions):
                if isinstance(s, dict) and s.get("id") == sess.get("id"):
                    ns = dict(s)
                    ns["access_token"] = new_access
                    ns["refresh_token"] = new_refresh
                    ns["token_type"] = "bearer"
                    ns["status"] = "authenticated"
                    ns["last_error_code"] = None
                    ns["last_error_message"] = None
                    ns["last_validation_ok"] = True
                    ns["last_validated_at"] = now
                    ns["access_token_expires_at"] = exp
                    ns["updated_at"] = now
                    sessions[i] = ns
                    sess = ns
                    break
            try:
                _save("auth_sessions.json", sessions)
            except Exception as e:
                return _err("CONFLICT", "Failed to persist refreshed session.", details=str(e))
            return {
                "superset_instance_id": inst_id,
                "session_id": sess.get("id"),
                "token_type": "bearer",
                "access_token": sess.get("access_token"),
                "refresh_token": sess.get("refresh_token"),
                "access_token_expires_at": sess.get("access_token_expires_at"),
                "authenticated_via": "refresh_token",
                "authenticated_at": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        # If refresh fails (no refresh_token) fall through to login

    # Login fallback requires username/password (since tool surface provides them; env fallback not available offline)
    if username is None or password is None:
        return _err("VALIDATION_ERROR", "username and password are required to authenticate when no valid/refreshable session exists.")

    # Upsert session by (superset_instance_id, username) when username not null
    # Enforce unique(superset_instance_id, username) where username is not null
    existing = None
    for s in sessions:
        if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("username") == username:
            existing = s
            break

    new_access = "access_" + uuid.uuid4().hex
    new_refresh = "refresh_" + uuid.uuid4().hex
    exp = (datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(hours=1)).isoformat() + "Z"

    if existing:
        # Must never overwrite a non-null stored username with null; here username is non-null
        updated = False
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == existing.get("id"):
                ns = dict(s)
                ns["username"] = s.get("username") if s.get("username") is not None else username
                ns["access_token"] = new_access
                ns["refresh_token"] = new_refresh
                ns["token_type"] = "bearer"
                ns["status"] = "authenticated"
                ns["access_token_expires_at"] = exp
                ns["last_validated_at"] = now
                ns["last_validation_ok"] = True
                ns["last_error_code"] = None
                ns["last_error_message"] = None
                ns["updated_at"] = now
                sessions[i] = ns
                sess = ns
                updated = True
                break
        if not updated:
            return _err("NOT_FOUND", "Auth session disappeared during update.")
    else:
        # Create new session; choose initial status transitions anonymous -> authenticated
        sid = "sess_" + uuid.uuid4().hex
        sess = {
            "id": sid,
            "superset_instance_id": inst_id,
            "username": username,
            "access_token": new_access,
            "refresh_token": new_refresh,
            "token_type": "bearer",
            "access_token_expires_at": exp,
            "last_validated_at": now,
            "last_validation_ok": True,
            "last_error_code": None,
            "last_error_message": None,
            "status": "authenticated",
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)

    try:
        _save("auth_sessions.json", sessions)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist authenticated session.", details=str(e))

    return {
        "superset_instance_id": inst_id,
        "session_id": sess.get("id"),
        "token_type": "bearer",
        "access_token": sess.get("access_token"),
        "refresh_token": sess.get("refresh_token"),
        "access_token_expires_at": sess.get("access_token_expires_at"),
        "authenticated_via": "login",
        "authenticated_at": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def superset_dashboard_list(page=None, page_size=None, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Defaults (Superset-like)
    if page is None: page = 1
    if page_size is None: page_size = 25

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")

    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
        assets = _load("superset_assets.json")
    except Exception as e:
        return _err("CONFLICT", "Failed to read datastore.", details=str(e))

    def _dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Choose deterministic active instance
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance configured.")
    active_instances.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Require a valid session/token
    inst_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id]
    def _token_valid(s):
        if not s or not s.get("access_token"): return False
        if s.get("status") != "authenticated": return False
        exp = _dt(s.get("access_token_expires_at"))
        if exp and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        return True
    valid_sess = None
    # choose most recently updated valid session
    inst_sessions.sort(key=lambda s: -int((_dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.now(datetime.timezone.utc)).timestamp()))
    for s in inst_sessions:
        if _token_valid(s):
            valid_sess = s
            break
    if not valid_sess:
        return _err("UNAUTHORIZED", "No valid Superset session/token available to list dashboards.")

    # No explicit permission model stored; if token valid, allow. (If needed, would return FORBIDDEN.)
    dashboards = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == inst_id
        and a.get("asset_type") == "dashboard"
        and a.get("status") != "deleted"
    ]

    # Deterministic ordering: name then superset_object_id then id
    dashboards.sort(key=lambda d: (
        (d.get("name") or "").lower(),
        d.get("superset_object_id") if isinstance(d.get("superset_object_id"), int) else 10**18,
        d.get("id") or ""
    ))

    total = len(dashboards)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = dashboards[start:end] if start < total else []

    total_pages = int(math.ceil(total / page_size)) if page_size else 0
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "result": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "total_pages": total_pages,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
        "superset_instance_id": inst_id,
        "latency_ms": latency_ms
    }

def superset_dashboard_get_by_id(dashboard_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_dashboard_get_by_id"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        # pick a working session for this instance; prefer authenticated, then others with token
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            # Must have a token to be usable for Superset calls
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(dashboard_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="dashboard_id must be integer")
        return _err("VALIDATION_ERROR", "`dashboard_id` must be an integer.", field="dashboard_id")
    if dashboard_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="dashboard_id must be positive")
        return _err("VALIDATION_ERROR", "`dashboard_id` must be a positive integer.", field="dashboard_id")

    # Rate limit: best-effort global 120/min if request_logs exists
    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    # Local cache lookup: do not error if not found in cache? Spec says NOT_FOUND if no accessible dashboard.
    dash = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != inst.get("id"):
            continue
        if a.get("asset_type") != "dashboard":
            continue
        if a.get("superset_object_id") == dashboard_id:
            dash = a
            break

    if not dash or dash.get("status") == "deleted":
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Dashboard not found in local cache", meta={"dashboard_id": dashboard_id})
        return _err("NOT_FOUND", "No accessible dashboard exists with that id.", dashboard_id=dashboard_id)

    # Return a Superset-like dashboard record based on cached payload
    payload = dash.get("payload") if isinstance(dash.get("payload"), dict) else {}
    result = {"id": dashboard_id}
    if dash.get("name") is not None:
        result["dashboard_title"] = dash.get("name")
    if dash.get("slug") is not None:
        result["slug"] = dash.get("slug")
    # include all cached payload fields as Superset would
    for k, v in payload.items():
        if k not in result:
            result[k] = v
    # include cache metadata
    result["_integration"] = {
        "asset_id": dash.get("id"),
        "superset_instance_id": dash.get("superset_instance_id"),
        "status": dash.get("status"),
        "last_synced_at": dash.get("last_synced_at"),
        "updated_at": dash.get("updated_at"),
    }

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"dashboard_id": dashboard_id})
    return {"dashboard": result}

def superset_dashboard_create(dashboard_title, json_metadata=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    def _log(status, credential_id=None, instance_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "superset_dashboard_create",
                "credential_id": credential_id,
                "superset_instance_id": instance_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - start) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate
    if not isinstance(dashboard_title, str) or not dashboard_title.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`dashboard_title` is required and must be a non-empty string", field="dashboard_title")
    if json_metadata is not None and not isinstance(json_metadata, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`json_metadata` must be an object when provided", field="json_metadata")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    assets = _load("superset_assets.json")

    def _ts(v):
        if not v:
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Superset instance configured")

    active_instances.sort(key=lambda r: (_ts(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
    # Find working (instance, session)
    chosen = None
    for inst in active_instances:
        iid = inst.get("id")
        usable = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == iid and s.get("status") == "authenticated" and s.get("access_token")]
        if usable:
            chosen = (inst, sorted(usable, key=lambda s: (_ts(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), s.get("id") or ""))[-1])
            break
    if not chosen:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No valid Superset session/token available")
    instance, sess = chosen
    instance_id = instance.get("id")

    # Validate token via /me simulation; update session
    now = datetime.datetime.utcnow().isoformat() + "Z"
    sess["last_validated_at"] = now
    sess["last_validation_ok"] = True
    sess["last_error_code"] = None
    sess["last_error_message"] = None
    sess["updated_at"] = now
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sess.get("id"):
            sessions[i] = sess
            break
    _save("auth_sessions.json", sessions)

    # CONFLICT heuristic: dashboards with same title (active/stale) in this instance
    existing = [a for a in assets if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "dashboard" and (a.get("status") != "deleted") and (a.get("name") or "").strip().lower() == dashboard_title.strip().lower()]
    if existing:
        _log("error", credential_id=sess.get("id"), instance_id=instance_id, error_code="CONFLICT")
        return _err("CONFLICT", "A dashboard with the same title already exists in this instance", dashboard_title=dashboard_title)

    # Create new "Superset" dashboard id deterministically: max+1 within instance dashboards
    existing_ids = [a.get("superset_object_id") for a in assets if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "dashboard" and isinstance(a.get("superset_object_id"), int)]
    new_id = (max(existing_ids) + 1) if existing_ids else 1

    # "Superset-provided" response payload
    payload = {
        "id": new_id,
        "dashboard_title": dashboard_title,
        "json_metadata": json_metadata if json_metadata is not None else {},
    }

    # Upsert asset keyed by (instance, type, object_id)
    match = None
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "dashboard" and a.get("superset_object_id") == new_id:
            match = a
            break

    if match is None:
        asset_row = {
            "id": "sasset_" + uuid.uuid4().hex,
            "superset_instance_id": instance_id,
            "asset_type": "dashboard",
            "superset_object_id": new_id,
            "superset_key": None,
            "name": dashboard_title,
            "slug": None,
            "database_asset_id": None,
            "dataset_asset_id": None,
            "schema_name": None,
            "table_name": None,
            "datasource_type": None,
            "viz_type": None,
            "payload": payload,
            "owners": None,
            "status": "active",
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now,
        }
        assets.append(asset_row)
    else:
        # revive/update
        match["name"] = dashboard_title
        match["payload"] = payload
        if match.get("status") == "deleted":
            # deleted -> no transitions allowed per lifecycle, so create a new row is safer in real systems.
            # Here we respect lifecycle by not transitioning; instead, return conflict.
            _log("error", credential_id=sess.get("id"), instance_id=instance_id, error_code="CONFLICT")
            return _err("CONFLICT", "Dashboard id is already deleted in cache and cannot be recreated with same id")
        match["status"] = "active"
        match["last_synced_at"] = now
        match["updated_at"] = now

    _save("superset_assets.json", assets)
    _log("ok", credential_id=sess.get("id"), instance_id=instance_id)
    return {"dashboard": payload, "superset_instance_id": instance_id}

