            "created_at": now,
            "updated_at": now,
        }
        assets.append(dash)
    else:
        dash = assets[found_idx]
        # resurrect if stale/deleted? deleted is terminal per schema; but business rule says delete sets deleted locally.
        # For update, treat as active (upsert on success).
        dash["updated_at"] = now
        dash["last_synced_at"] = now
        dash["status"] = "active"

    # Apply updates into payload and selected normalized fields
    payload = dash.get("payload") if isinstance(dash.get("payload"), dict) else {}
    payload_new = copy.deepcopy(payload)
    for k, v in data.items():
        payload_new[k] = v
    dash["payload"] = payload_new
    # normalize common Superset fields
    if "dashboard_title" in data and isinstance(data.get("dashboard_title"), str):
        dash["name"] = data.get("dashboard_title")
    if "slug" in data and (isinstance(data.get("slug"), str) or data.get("slug") is None):
        dash["slug"] = data.get("slug")

    _save("superset_assets.json", assets)

    # Return updated dashboard record
    result = {"id": dashboard_id}
    if dash.get("name") is not None:
        result["dashboard_title"] = dash.get("name")
    if dash.get("slug") is not None:
        result["slug"] = dash.get("slug")
    for k, v in (dash.get("payload") or {}).items():
        if k not in result:
            result[k] = v
    result["_integration"] = {
        "asset_id": dash.get("id"),
        "superset_instance_id": dash.get("superset_instance_id"),
        "status": dash.get("status"),
        "last_synced_at": dash.get("last_synced_at"),
        "updated_at": dash.get("updated_at"),
