    if dashboard_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="dashboard_id must be positive")
        return _err("VALIDATION_ERROR", "`dashboard_id` must be a positive integer.", field="dashboard_id")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    idx = None
    for i, a in enumerate(assets):
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst.get("id") and a.get("asset_type") == "dashboard" and a.get("superset_object_id") == dashboard_id:
            idx = i
            break
    if idx is None:
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Dashboard not found in local cache", meta={"dashboard_id": dashboard_id})
        return _err("NOT_FOUND", "Dashboard not found or not accessible.", dashboard_id=dashboard_id)

    dash = assets[idx]
    # Lifecycle transition: active/stale -> deleted; deleted terminal.
    if dash.get("status") == "deleted":
        # idempotent delete: Superset delete endpoint is typically idempotent-ish; here treat as success without changing state
        _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"dashboard_id": dashboard_id, "idempotent": True})
        return {"result": {"id": dashboard_id, "deleted": True, "already_deleted": True}}

    now = _now_iso()
    dash["status"] = "deleted"
    dash["updated_at"] = now
    dash["last_synced_at"] = now
    assets[idx] = dash
    _save("superset_assets.json", assets)

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"dashboard_id": dashboard_id})
    return {"result": {"id": dashboard_id, "deleted": True}}

def superset_chart_list(page=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log + rate limit (best-effort, only if collection exists) ---
    request_logs_name = "request_logs.json"
    req_logs = _load(request_logs_name)
    def _log(status_code, credential_id=None, detail=None):
        nonlocal req_logs
        try:
            row = {
                "id": "rql_" + uuid.uuid4().hex,
                "endpoint": "superset_chart_list",
                "credential_id": credential_id,
                "status": status_code,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
            if isinstance(req_logs, list):
                req_logs.append(row)
                _save(request_logs_name, req_logs)
        except Exception:
            return

    # rudimentary rate limiting if request_logs exists: 120 req/min global
    if isinstance(req_logs, list) and req_logs:
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in req_logs[-2000:]:
            try:
                if r.get("created_at") and r["created_at"] >= cutoff:
                    recent += 1
            except Exception:
                pass
        if recent >= 120:
            _log("RATE_LIMIT", None, "global_120_per_min")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit="120/min")

    # --- validate inputs ---
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        _log("VALIDATION_ERROR", None, "invalid_page")
        return _err("VALIDATION_ERROR", "Invalid `page`; must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("VALIDATION_ERROR", None, "invalid_page_size")
        return _err("VALIDATION_ERROR", "Invalid `page_size`; must be an integer between 1 and 200.", field="page_size")

    # --- resolve an authenticated session + active instance deterministically ---
    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    if not isinstance(instances, list) or not isinstance(sessions, list):
        _log("UNAUTHORIZED", None, "store_unavailable")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log("UNAUTHORIZED", None, "no_active_instance")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    def _created_key(i):
        return i.get("created_at") or ""
    active_instances.sort(key=_created_key)

    chosen = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst.get("id")
        if not inst_id:
            continue
        candidates = []
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != inst_id:
                continue
            if s.get("token_type") != "bearer":
                continue
            if s.get("status") != "authenticated":
                continue
            if not s.get("access_token"):
                continue
            candidates.append(s)
        if candidates:
            # deterministic: oldest created_at
            candidates.sort(key=lambda x: x.get("created_at") or "")
            chosen = inst
            chosen_session = candidates[0]
            break

    if not chosen_session:
        _log("UNAUTHORIZED", None, "no_authenticated_session")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    # --- list charts from local cache (superset_assets) ---
    assets = _load("superset_assets.json")
    if not isinstance(assets, list):
        _log("UNAUTHORIZED", chosen_session.get("id"), "assets_store_unavailable")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    charts = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != chosen.get("id"):
            continue
        if a.get("asset_type") != "chart":
            continue
        if a.get("status") == "deleted":
            continue
        charts.append(a)

    # deterministic sort: name then superset_object_id
    def _sort_key(a):
        n = a.get("name") or ""
        oid = a.get("superset_object_id")
        try:
            oidv = int(oid) if oid is not None else 0
        except Exception:
            oidv = 0
        return (n.lower(), oidv)
    charts.sort(key=_sort_key)

    total = len(charts)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = charts[start:end] if start < total else []
    has_more = end < total

    # return in a Superset-like envelope
    resp = {
        "result": [
            {
                "id": r.get("superset_object_id"),
                "slice_name": r.get("name"),
                "viz_type": r.get("viz_type"),
                "datasource_type": r.get("datasource_type"),
                "datasource_id": (r.get("payload") or {}).get("datasource_id") if isinstance(r.get("payload"), dict) else None,
                "changed_on_utc": r.get("updated_at"),
                "_cache": {"asset_id": r.get("id"), "status": r.get("status"), "last_synced_at": r.get("last_synced_at")},
            }
            for r in page_rows
        ],
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "pages": int(math.ceil(total / float(page_size))) if page_size else 0,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
        "superset_instance": {
            "id": chosen.get("id"),
            "base_url": chosen.get("base_url"),
            "display_name": chosen.get("display_name"),
        },
    }
    _log("OK", chosen_session.get("id"), None)
    return resp

