        _log("error", error_code="UNAUTHORIZED", error_message="no active superset instance")
        return _err("UNAUTHORIZED", "No active Superset instance configured.")
    active_instances.sort(key=lambda r: ((_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)), r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        iid = inst.get("id")
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == iid and s.get("status") == "authenticated" and s.get("access_token")]
        if cand:
            cand.sort(key=lambda s: (_parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), s.get("id") or ""), reverse=True)
            chosen_instance = inst
            chosen_session = cand[0]
            break
    if not chosen_instance:
        _log("error", error_code="UNAUTHORIZED", error_message="no valid superset session/token is available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    instance_id = chosen_instance.get("id")
    session_id = chosen_session.get("id")

    # Ensure datasource exists in local cache if possible (relax: only validate if present in cache)
    # Some stores may not have dataset assets; do not hard-fail.
    # We'll link dataset_asset_id if found.
    dataset_asset_id = None
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "dataset" and a.get("superset_object_id") == datasource_id and a.get("status") != "deleted":
            dataset_asset_id = a.get("id")
            break

    # Create new chart id deterministically: next available superset_object_id in this instance for asset_type chart
    max_id = 0
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "chart":
            oid = a.get("superset_object_id")
            if isinstance(oid, int) and oid > max_id:
                max_id = oid
    new_chart_id = max_id + 1
    now = _now_iso()

    new_asset = {
        "id": _new_asset_id(),
        "superset_instance_id": instance_id,
        "asset_type": "chart",
        "superset_object_id": new_chart_id,
        "superset_key": None,
        "name": slice_name,
        "slug": None,
        "database_asset_id": None,
        "dataset_asset_id": dataset_asset_id,
        "schema_name": None,
        "table_name": None,
        "datasource_type": datasource_type,
        "viz_type": viz_type,
        "payload": {"slice_name": slice_name, "datasource_id": datasource_id, "datasource_type": datasource_type, "viz_type": viz_type, "params": params},
        "owners": None,
        "status": "active",
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce uniqueness (superset_instance_id, asset_type, superset_object_id)
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "chart" and a.get("superset_object_id") == new_chart_id:
            _log("error", instance_id=instance_id, session_id=session_id, error_code="CONFLICT", error_message="duplicate chart id")
            return _err("CONFLICT", "Chart id conflict while creating chart. Please retry.", chart_id=new_chart_id)

    assets.append(new_asset)
    if isinstance(assets_obj, dict) and "rows" in assets_obj:
        assets_obj["rows"] = assets
        _save("superset_assets.json", assets_obj)
    else:
        _save("superset_assets.json", assets)

    _log("success", instance_id=instance_id, session_id=session_id, meta={"chart_id": new_chart_id})
    return {"chart_id": new_chart_id, "superset_instance_id": instance_id, "asset": new_asset}

def superset_chart_update(chart_id, data, **_extra):
    import json, os, datetime, time, uuid, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_chart_update"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(chart_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="chart_id must be integer")
        return _err("VALIDATION_ERROR", "`chart_id` must be an integer.", field="chart_id")
    if chart_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="chart_id must be positive")
        return _err("VALIDATION_ERROR", "`chart_id` must be a positive integer.", field="chart_id")
    if not isinstance(data, dict):
        _log("error", error_code="VALIDATION_ERROR", error_message="data must be object")
        return _err("VALIDATION_ERROR", "`data` must be an object.", field="data")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    now = _now_iso()
    found_idx = None
    for i, a in enumerate(assets):
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst.get("id") and a.get("asset_type") == "chart" and a.get("superset_object_id") == chart_id:
            found_idx = i
            break

    if found_idx is None:
        chart = {
            "id": _new_id("ssa"),
            "superset_instance_id": inst.get("id"),
            "asset_type": "chart",
            "superset_object_id": chart_id,
            "superset_key": None,
            "name": None,
            "slug": None,
            "database_asset_id": None,
            "dataset_asset_id": None,
            "schema_name": None,
            "table_name": None,
            "datasource_type": None,
            "viz_type": None,
            "payload": {},
            "owners": None,
            "status": "active",
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now,
        }
        assets.append(chart)
    else:
        chart = assets[found_idx]
        chart["updated_at"] = now
        chart["last_synced_at"] = now
        chart["status"] = "active"

    payload = chart.get("payload") if isinstance(chart.get("payload"), dict) else {}
    payload_new = copy.deepcopy(payload)
    for k, v in data.items():
        payload_new[k] = v
    chart["payload"] = payload_new

    # normalize common fields
    if "slice_name" in data and isinstance(data.get("slice_name"), str):
        chart["name"] = data.get("slice_name")
    if "viz_type" in data and isinstance(data.get("viz_type"), str):
        chart["viz_type"] = data.get("viz_type")
    if "datasource_type" in data and isinstance(data.get("datasource_type"), str):
        chart["datasource_type"] = data.get("datasource_type")
    if "database_asset_id" in data and (isinstance(data.get("database_asset_id"), str) or data.get("database_asset_id") is None):
        chart["database_asset_id"] = data.get("database_asset_id")
    if "dataset_asset_id" in data and (isinstance(data.get("dataset_asset_id"), str) or data.get("dataset_asset_id") is None):
        chart["dataset_asset_id"] = data.get("dataset_asset_id")

    # enforce cache constraint for chart: must have database_asset_id or dataset_asset_id
    if not chart.get("database_asset_id") and not chart.get("dataset_asset_id"):
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="VALIDATION_ERROR", error_message="chart requires database_asset_id or dataset_asset_id", meta={"chart_id": chart_id})
        return _err("VALIDATION_ERROR", "Chart cache record requires `database_asset_id` or `dataset_asset_id` to be set (integration constraint).", chart_id=chart_id)

    _save("superset_assets.json", assets)

    result = {"id": chart_id}
    if chart.get("name") is not None:
        result["slice_name"] = chart.get("name")
    if chart.get("viz_type") is not None:
        result["viz_type"] = chart.get("viz_type")
    if chart.get("datasource_type") is not None:
        result["datasource_type"] = chart.get("datasource_type")
    if chart.get("dataset_asset_id") is not None:
        result["dataset_asset_id"] = chart.get("dataset_asset_id")
    if chart.get("database_asset_id") is not None:
        result["database_asset_id"] = chart.get("database_asset_id")
    for k, v in (chart.get("payload") or {}).items():
        if k not in result:
            result[k] = v
    result["_integration"] = {
        "asset_id": chart.get("id"),
        "superset_instance_id": chart.get("superset_instance_id"),
        "status": chart.get("status"),
        "last_synced_at": chart.get("last_synced_at"),
        "updated_at": chart.get("updated_at"),
    }

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"chart_id": chart_id})
    return {"chart": result}

