def superset_database_list(page=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"
    def _log(endpoint, instance_id, session_id, status, start_ts, error_code=None):
        for fname in ("request_logs.json", "usage_logs.json", "api_request_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                logs.append({
                    "id": _new_id("req"),
                    "endpoint": endpoint,
                    "superset_instance_id": instance_id,
                    "auth_session_id": session_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - start_ts) * 1000),
                    "created_at": _now()
                })
                _save(fname, logs)
                break

    start = time.time()
    endpoint = "superset_database_list"

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20

    if not isinstance(page, int) or page < 1:
        resp = _err("VALIDATION_ERROR", "page must be an integer >= 1")
        _log(endpoint, None, None, "error", start, error_code="VALIDATION_ERROR")
        return resp
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        resp = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500")
        _log(endpoint, None, None, "error", start, error_code="VALIDATION_ERROR")
        return resp

    instances = _load("superset_instances.json")
    active_instances = [i for i in instances if i.get("status") == "active"]
    if not active_instances:
        resp = _err("UNAUTHORIZED", "No active Superset instance is configured")
        _log(endpoint, None, None, "error", start, error_code="UNAUTHORIZED")
        return resp
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    instance = active_instances[0]
    instance_id = instance.get("id")

    sessions = _load("auth_sessions.json")
    usable = []
    for s in sessions:
        if s.get("superset_instance_id") != instance_id:
            continue
        if s.get("status") != "authenticated":
            continue
        if s.get("token_type") != "bearer":
            continue
        if not s.get("access_token"):
            continue
        usable.append(s)
    if not usable:
        resp = _err("UNAUTHORIZED", "Superset session is missing or expired")
        _log(endpoint, instance_id, None, "error", start, error_code="UNAUTHORIZED")
        return resp
    usable.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or "", r.get("id") or ""), reverse=True)
    session_id = usable[0].get("id")

    assets = _load("superset_assets.json")
    db_assets = [a for a in assets if a.get("superset_instance_id") == instance_id and a.get("asset_type") == "database" and a.get("status") != "deleted"]

    # Deterministic ordering: by name then superset_object_id then created_at then id
    db_assets.sort(key=lambda a: (
        (a.get("name") or "").lower(),
        a.get("superset_object_id") if isinstance(a.get("superset_object_id"), int) else 10**18,
        a.get("created_at") or "",
        a.get("id") or ""
    ))

    total = len(db_assets)
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    page_items = db_assets[start_idx:end_idx]

    def _summary_payload(p):
        if not isinstance(p, dict):
            return None
        # Return only a safe summary; do not expose secrets (sqlalchemy_uri)
        summary = {}
        for k in ("backend", "engine", "expose_in_sqllab", "allow_csv_upload", "impersonate_user", "extra", "catalog", "schemas"):
            if k in p:
                summary[k] = p.get(k)
        return summary or None

    results = []
    for a in page_items:
        results.append({
            "id": a.get("superset_object_id"),
            "name": a.get("name"),
            "configuration_method": (a.get("payload") or {}).get("configuration_method") if isinstance(a.get("payload"), dict) else None,
            "engine": (a.get("payload") or {}).get("engine") if isinstance(a.get("payload"), dict) else None,
            "configuration_summary": _summary_payload(a.get("payload")),
            "status": a.get("status"),
            "last_synced_at": a.get("last_synced_at"),
        })

    body = {
        "result": results,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": end_idx < total,
            "next_page": (page + 1) if end_idx < total else None
        }
    }
    _log(endpoint, instance_id, session_id, "ok", start)
    return body

def superset_database_get_by_id(database_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_database_get_by_id"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _redact_uri(uri):
        if not isinstance(uri, str):
            return uri
        # Replace password-like part user:pass@ with user:***@
        return re.sub(r"(?i)(://[^:/?#]+:)([^@/?#]+)(@)", r"\1***\3", uri)

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")
    if database_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be positive integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    db = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != inst.get("id"):
            continue
        if a.get("asset_type") != "database":
            continue
        if a.get("superset_object_id") == database_id:
            db = a
            break

    if not db or db.get("status") == "deleted":
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Database not found in local cache", meta={"database_id": database_id})
        return _err("NOT_FOUND", "Database not found or not visible.", database_id=database_id)

    payload = db.get("payload") if isinstance(db.get("payload"), dict) else {}
    # redact any stored uri-like fields for response safety
    payload_safe = {}
    for k, v in payload.items():
        if k in ("sqlalchemy_uri", "uri", "connection", "connection_string"):
            payload_safe[k] = _redact_uri(v)
        else:
            payload_safe[k] = v

    result = {"id": database_id}
    if db.get("name") is not None:
        result["database_name"] = db.get("name")
    for k, v in payload_safe.items():
        if k not in result:
            result[k] = v
    result["_integration"] = {
        "asset_id": db.get("id"),
        "superset_instance_id": db.get("superset_instance_id"),
        "status": db.get("status"),
        "last_synced_at": db.get("last_synced_at"),
        "updated_at": db.get("updated_at"),
    }

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"database_id": database_id})
    return {"database": result}

def superset_database_create(engine, configuration_method, database_name, sqlalchemy_uri, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_database_create"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    # rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list) and logs:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-4000:]:
            ts = _parse_dt((r or {}).get("timestamp") or (r or {}).get("created_at"))
            if ts and ts.replace(tzinfo=None) >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="global_120_per_min")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit="120/min")

    for name, val in (("engine", engine), ("configuration_method", configuration_method), ("database_name", database_name), ("sqlalchemy_uri", sqlalchemy_uri)):
        if not isinstance(val, str) or not val.strip():
            _log("error", error_code="VALIDATION_ERROR", error_message=f"{name} required")
            return _err("VALIDATION_ERROR", f"{name} must be a non-empty string.", field=name)

    engine = engine.strip()
    configuration_method = configuration_method.strip()
    database_name = database_name.strip()
    sqlalchemy_uri_in = sqlalchemy_uri.strip()

    # Relax validation: accept any non-empty string; if it resembles scheme:// then ok; else still accept (Superset supports many forms)
    if len(sqlalchemy_uri_in) < 3:
        _log("error", error_code="VALIDATION_ERROR", error_message="sqlalchemy_uri too short")
        return _err("VALIDATION_ERROR", "sqlalchemy_uri must be a non-empty connection string.", field="sqlalchemy_uri")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    assets = _load("superset_assets.json")
    if not isinstance(instances, list) or not isinstance(sessions, list) or not isinstance(assets, list):
        _log("error", error_code="CONFLICT", error_message="Datastore invalid")
        return _err("CONFLICT", "Failed to read datastore.")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and i.get("id")]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance configured.")

    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))

    chosen_inst = None
    chosen_sess = None
    for inst in active_instances:
        iid = inst["id"]
        sess_cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == iid and s.get("access_token") and s.get("status") == "authenticated"]
        if sess_cand:
            sess_cand.sort(key=lambda s: (_parse_dt(s.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), s.get("id") or ""))
            chosen_inst, chosen_sess = inst, sess_cand[0]
            break

    if not chosen_inst or not chosen_sess:
        _log("error", error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    # conflict check: same instance + asset_type database + name matches OR payload database_name matches
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != chosen_inst["id"] or a.get("asset_type") != "database":
            continue
        if a.get("status") != "deleted" and (a.get("name") == database_name or (isinstance(a.get("payload"), dict) and a["payload"].get("database_name") == database_name)):
            _log("error", instance_id=chosen_inst.get("id"), session_id=chosen_sess.get("id"), error_code="CONFLICT", error_message="Database already exists")
            return _err("CONFLICT", "A database with the same name already exists.", database_name=database_name)

    # allocate new superset database id within instance
    max_id = 0
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == chosen_inst["id"] and a.get("asset_type") == "database" and isinstance(a.get("superset_object_id"), int):
            max_id = max(max_id, a["superset_object_id"])
    new_db_id = max_id + 1 if max_id > 0 else 1

    # Treat sqlalchemy_uri as secret: store only redacted unless obviously already secret-managed/encrypted
    def _redact(uri):
        # remove password portion user:pass@ -> user:***@
        return re.sub(r"(?P<scheme>^[a-zA-Z][a-zA-Z0-9+.\-]*://)(?P<user>[^:/?#]+)(?::(?P<pw>[^@/?#]*))?@", lambda m: m.group("scheme") + m.group("user") + (":***@" if m.group("pw") is not None else "@"), uri)

    uri_to_store = None
    if re.search(r"(vault:|kms:|secret|encrypted|\*{3}|redacted)", sqlalchemy_uri_in, re.IGNORECASE):
        uri_to_store = sqlalchemy_uri_in
    else:
        uri_to_store = _redact(sqlalchemy_uri_in)

    now = _now_iso()
    payload = {
        "id": new_db_id,
        "database_name": database_name,
        "engine": engine,
        "configuration_method": configuration_method,
        "sqlalchemy_uri": uri_to_store,
    }

    asset_row = {
        "id": "ssa_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "superset_instance_id": chosen_inst["id"],
        "asset_type": "database",
        "superset_object_id": new_db_id,
        "superset_key": None,
        "name": database_name,
        "slug": None,
        "database_asset_id": None,
        "dataset_asset_id": None,
        "schema_name": None,
        "table_name": None,
        "datasource_type": None,
        "viz_type": None,
        "payload": payload,
        "owners": None,
        "status": "active",
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }
    assets.append(asset_row)
    _save("superset_assets.json", assets)

    _log("ok", instance_id=chosen_inst.get("id"), session_id=chosen_sess.get("id"))
    return payload

def superset_database_get_tables(database_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, instance_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset",
            "endpoint": "superset_database_get_tables",
            "superset_instance_id": instance_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be an integer")
        return _err("VALIDATION_ERROR", "database_id must be an integer")

    # Resolve active superset instance deterministically (lowest created_at)
    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        instances = []
    active_instances = [r for r in instances if isinstance(r, dict) and r.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance configured")
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Resolve an authenticated session for this instance (any username or anonymous if authenticated)
    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    def _is_session_usable(s):
        if not isinstance(s, dict):
            return False
        if s.get("superset_instance_id") != inst_id:
            return False
        st = s.get("status")
        if st != "authenticated":
            return False
        # Must have access_token to call Superset
        if not s.get("access_token"):
            return False
        return True

    usable_sessions = [s for s in sessions if _is_session_usable(s)]
    if not usable_sessions:
        _log("error", instance_id=inst_id, error_code="UNAUTHORIZED", error_message="Missing or expired Superset session")
        return _err("UNAUTHORIZED", "Missing or expired Superset session")

    # Find database asset in local cache for this instance
    assets = _load("superset_assets.json")
    if not isinstance(assets, list):
        assets = []
    db_asset = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst_id and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id:
            # Visible means not deleted
            if a.get("status") != "deleted":
                db_asset = a
            break
    if not db_asset:
        _log("error", instance_id=inst_id, credential_id=usable_sessions[0].get("id"), error_code="NOT_FOUND", error_message="Database not found")
        return _err("NOT_FOUND", "Database not found or not visible")

    # Offline behavior: return best-effort cached tables from payload if present.
    payload = db_asset.get("payload") if isinstance(db_asset.get("payload"), dict) else {}
    tables = payload.get("tables")
    if not isinstance(tables, list):
        tables = []

    # Update last_synced_at (business rule allows attaching response data and updating sync timestamp)
    try:
        db_asset["last_synced_at"] = now
        db_asset["updated_at"] = now
        # persist asset update
        for i, a in enumerate(assets):
            if isinstance(a, dict) and a.get("id") == db_asset.get("id"):
                assets[i] = db_asset
                break
        _save("superset_assets.json", assets)
    except Exception:
        _log("error", instance_id=inst_id, credential_id=usable_sessions[0].get("id"), error_code="BAD_GATEWAY", error_message="Failed to update local cache")
        return _err("BAD_GATEWAY", "Failed to update local cache")

    _log("ok", instance_id=inst_id, credential_id=usable_sessions[0].get("id"))
    return {
        "tables": tables,
        "database_id": database_id,
        "superset_instance_id": inst_id,
        "cached": True
    }

