            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be an integer")
        return _err("VALIDATION_ERROR", "database_id must be an integer")
    if not isinstance(data, dict):
        _log("error", error_code="VALIDATION_ERROR", error_message="data must be an object")
        return _err("VALIDATION_ERROR", "data must be an object")

    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        instances = []
    active_instances = [r for r in instances if isinstance(r, dict) and r.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance configured")
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    inst = active_instances[0]
    inst_id = inst.get("id")

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    usable_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and s.get("access_token")]
    if not usable_sessions:
        _log("error", instance_id=inst_id, error_code="UNAUTHORIZED", error_message="Missing or expired Superset session")
        return _err("UNAUTHORIZED", "Missing or expired Superset session")
    cred_id = usable_sessions[0].get("id")

    assets = _load("superset_assets.json")
    if not isinstance(assets, list):
        assets = []

    # Find existing db asset
    idx = None
    db_asset = None
    for i, a in enumerate(assets):
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst_id and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id:
            if a.get("status") != "deleted":
                db_asset = a
                idx = i
            break
    if not db_asset:
        _log("error", instance_id=inst_id, credential_id=cred_id, error_code="NOT_FOUND", error_message="Database not found")
        return _err("NOT_FOUND", "Database not found or not visible")

    # Apply update to payload; treat sqlalchemy_uri as secret (redact)
    def _redact_uri(uri):
        try:
            m = re.match(r"^([a-zA-Z][a-zA-Z0-9+.\-]*://)(.*)$", uri)
            if not m:
                return "***"
            prefix = m.group(1)
            rest = m.group(2)
            if "@" in rest:
                creds, hostpart = rest.split("@", 1)
                if ":" in creds:
                    return prefix + "***:***@" + hostpart
                return prefix + "***@" + hostpart
            return prefix + rest
        except Exception:
            return "***"

    new_payload = db_asset.get("payload") if isinstance(db_asset.get("payload"), dict) else {}
    new_payload = copy.deepcopy(new_payload)

    update_data = copy.deepcopy(data)

    # Redact secret
    if "sqlalchemy_uri" in update_data:
        v = update_data.get("sqlalchemy_uri")
        if v is not None and not isinstance(v, str):
            _log("error", instance_id=inst_id, credential_id=cred_id, error_code="VALIDATION_ERROR", error_message="sqlalchemy_uri must be a string")
            return _err("VALIDATION_ERROR", "sqlalchemy_uri must be a string")
        # Store only redacted version unless explicitly marked as secret-managed/encrypted
        secret_managed = bool(update_data.get("sqlalchemy_uri_secret_managed")) or bool(update_data.get("encrypted") is True)
        if secret_managed:
            # store a marker only, never the plaintext
            update_data["sqlalchemy_uri"] = {"secret_managed": True}
        else:
            update_data["sqlalchemy_uri"] = _redact_uri(v or "")
    # Merge
    for k, v in update_data.items():
        new_payload[k] = v

    # Optionally update display name if provided by Superset-like fields
    # Keep local 'name' in sync if data includes 'database_name' or 'name'
    name = None
    if isinstance(data.get("database_name"), str) and data.get("database_name").strip():
        name = data.get("database_name").strip()
    elif isinstance(data.get("name"), str) and data.get("name").strip():
        name = data.get("name").strip()

    try:
        db_asset["payload"] = new_payload
        if name is not None:
            db_asset["name"] = name
        db_asset["status"] = "active"
        db_asset["last_synced_at"] = now
        db_asset["updated_at"] = now
        assets[idx] = db_asset
        _save("superset_assets.json", assets)
    except Exception:
        _log("error", instance_id=inst_id, credential_id=cred_id, error_code="BAD_GATEWAY", error_message="Failed to persist update")
        return _err("BAD_GATEWAY", "Failed to persist update")

    _log("ok", instance_id=inst_id, credential_id=cred_id)
    return {
        "database": db_asset,
        "superset_instance_id": inst_id,
        "updated": True
    }

def superset_database_delete(database_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_database_delete"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")
    if database_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be positive integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    idx = None
    for i, a in enumerate(assets):
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst.get("id") and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id:
            idx = i
            break
    if idx is None:
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Database not found in local cache", meta={"database_id": database_id})
        return _err("NOT_FOUND", "Database not found or not visible.", database_id=database_id)

    db = assets[idx]
    if db.get("status") == "deleted":
        _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"database_id": database_id, "idempotent": True})
        return {"result": {"id": database_id, "deleted": True, "already_deleted": True}}

    now = _now_iso()
    db["status"] = "deleted"
    db["updated_at"] = now
    db["last_synced_at"] = now
    assets[idx] = db

    # Mark dependent cached objects stale (do not delete)
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != inst.get("id"):
            continue
        if a.get("database_asset_id") == db.get("id") and a.get("status") == "active":
            a["status"] = "stale"
            a["updated_at"] = now

    _save("superset_assets.json", assets)

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"database_id": database_id})
    return {"result": {"id": database_id, "deleted": True}}

