def superset_database_get_connection(database_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_database_get_connection"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _redact_uri(uri):
        if not isinstance(uri, str):
            return uri
        return re.sub(r"(?i)(://[^:/?#]+:)([^@/?#]+)(@)", r"\1***\3", uri)

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")
    if database_id <= 0:
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be positive integer")
        return _err("VALIDATION_ERROR", "`database_id` must be a positive integer.", field="database_id")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    db = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") == inst.get("id") and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id and a.get("status") != "deleted":
            db = a
            break
    if not db:
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Database not found in local cache", meta={"database_id": database_id})
        return _err("NOT_FOUND", "Database not found or not visible.", database_id=database_id)

    payload = db.get("payload") if isinstance(db.get("payload"), dict) else {}
    conn = payload.get("connection")
    if not isinstance(conn, dict):
        # fallback: build minimal connection info from known fields if present
        conn = {}
        if isinstance(payload.get("sqlalchemy_uri"), str):
            conn["sqlalchemy_uri"] = _redact_uri(payload.get("sqlalchemy_uri"))

    # redact sensitive values
    conn_safe = {}
    for k, v in conn.items():
        if k in ("sqlalchemy_uri", "uri", "connection_string"):
            conn_safe[k] = _redact_uri(v)
        else:
            conn_safe[k] = v

    # attach back (allowed by business rule: may attach response data to payload and update last_synced_at)
    now = _now_iso()
    db_payload = payload.copy()
    db_payload["connection"] = conn_safe
    db["payload"] = db_payload
    db["last_synced_at"] = now
    db["updated_at"] = now
    # persist change
    for i, a in enumerate(assets):
        if isinstance(a, dict) and a.get("id") == db.get("id"):
            assets[i] = db
            break
    _save("superset_assets.json", assets)

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"database_id": database_id})
    return {"database_id": database_id, "connection": conn_safe}

def superset_database_get_function_names(database_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance_id=None, session_id=None, error=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool": "superset_database_get_function_names",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(database_id, int):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "database_id must be an integer"})
        return _err("VALIDATION_ERROR", "database_id must be an integer")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    assets = _load("superset_assets.json")

    # Choose active instance deterministically
    active_instances = [i for i in instances if i.get("status") == "active"]
    if not active_instances:
        _log("error", error={"code": "UNAUTHORIZED", "message": "No active Superset instance configured"})
        return _err("UNAUTHORIZED", "No active Superset instance configured")

    def _dt(v):
        try:
            if not v: return None
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    active_instances.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
    instance_id = active_instances[0].get("id")

    # Must have authenticated session (tool docs mention UNAUTHORIZED/FORBIDDEN; we only model UNAUTHORIZED here)
    candidate_sessions = [s for s in sessions if s.get("superset_instance_id") == instance_id and s.get("status") == "authenticated" and s.get("access_token")]
    if not candidate_sessions:
        _log("error", instance_id=instance_id, error={"code": "UNAUTHORIZED", "message": "Superset session is missing/expired"})
        return _err("UNAUTHORIZED", "Superset session is missing/expired")
    candidate_sessions.sort(key=lambda r: (_dt(r.get("last_validated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), _dt(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    session_id = candidate_sessions[0].get("id")

    # Find database asset
    db_assets = [a for a in assets if a.get("superset_instance_id") == instance_id and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id and a.get("status") != "deleted"]
    if not db_assets:
        _log("error", instance_id=instance_id, session_id=session_id, error={"code": "NOT_FOUND", "message": "Database not found"})
        return _err("NOT_FOUND", "Database not found")
    db_asset = sorted(db_assets, key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))[0]

    # Offline: return cached function names if present; otherwise empty list.
    payload = db_asset.get("payload") if isinstance(db_asset.get("payload"), dict) else {}
    meta = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    fns = meta.get("function_names")
    if isinstance(fns, list):
        function_names = [x for x in fns if isinstance(x, str)]
    else:
        function_names = []

    # Touch sync timestamps
    db_asset["last_synced_at"] = now
    db_asset["updated_at"] = now
    _save("superset_assets.json", assets)

    _log("ok", instance_id=instance_id, session_id=session_id)
    return {
        "superset_instance_id": instance_id,
        "database_id": database_id,
        "function_names": function_names,
        "count": len(function_names),
        "cached": isinstance(fns, list),
    }

def superset_database_get_related_objects(database_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status, credential_id=None, superset_instance_id=None, error_code=None, error_message=None, meta=None, started=None):
        # Best-effort observable dynamics; only if a log collection exists.
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                ts = _now()
                latency_ms = None
                if started is not None:
                    latency_ms = int((time.time() - started) * 1000)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                    "endpoint": "superset_database_get_related_objects",
                    "timestamp": ts,
                    "status": status,
                    "latency_ms": latency_ms,
                    "credential_id": credential_id,
                    "superset_instance_id": superset_instance_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "meta": meta or {}
                })
                _save(fname, logs)
                break

    started = time.time()

    # Validate inputs
    if not isinstance(database_id, int):
        _log("error", error_code="VALIDATION_ERROR", error_message="database_id must be an integer", started=started)
        return _err("VALIDATION_ERROR", "database_id must be an integer")

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    assets = _ensure_list(_load("superset_assets.json"))

    # Resolve an authorized context: active instance + an auth session that can serve requests (authenticated)
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured", started=started)
        return _err("UNAUTHORIZED", "No active Superset instance configured")

    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))

    chosen = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst.get("id")
        if not inst_id:
            continue
        # Need any authenticated session; otherwise treat as unauthorized for operations that require Superset access.
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and s.get("token_type") == "bearer"]
        if cand:
            cand.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min, r.get("id") or ""))
            chosen = inst
            chosen_session = cand[-1]
            break

    if chosen is None:
        _log("error", error_code="UNAUTHORIZED", error_message="No authenticated Superset session available", started=started)
        return _err("UNAUTHORIZED", "No authenticated Superset session available")

    instance_id = chosen["id"]

    # Find the database asset for this instance
    db_assets = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "database"
        and a.get("superset_object_id") == database_id
        and a.get("status") != "deleted"
    ]
    if not db_assets:
        _log("error", credential_id=chosen_session.get("id"), superset_instance_id=instance_id, error_code="NOT_FOUND",
             error_message="Database not found", started=started, meta={"database_id": database_id})
        return _err("NOT_FOUND", "Database not found", database_id=database_id)

    db_asset = sorted(db_assets, key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))[0]

    # Related datasets/charts/dashboards
    datasets = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "dataset"
        and a.get("database_asset_id") == db_asset.get("id")
        and a.get("status") != "deleted"
    ]
    dataset_ids = {d.get("id") for d in datasets if d.get("id")}
    charts = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "chart"
        and a.get("status") != "deleted"
        and (
            (a.get("dataset_asset_id") in dataset_ids) or
            (a.get("database_asset_id") == db_asset.get("id"))
        )
    ]
    dashboards = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "dashboard"
        and a.get("status") != "deleted"
    ]

    # If dashboard payload contains chart/dataset references, include only those; otherwise return dashboards as "unknown dependency"
    related_dashboards = []
    chart_object_ids = {c.get("superset_object_id") for c in charts if isinstance(c.get("superset_object_id"), int)}
    dataset_object_ids = {d.get("superset_object_id") for d in datasets if isinstance(d.get("superset_object_id"), int)}

    for d in dashboards:
        p = d.get("payload") if isinstance(d.get("payload"), dict) else {}
        # Heuristics: common superset fields: "charts", "slices", "position_json", etc.
        dep = False
        if isinstance(p.get("charts"), list):
            for x in p.get("charts"):
                if isinstance(x, dict) and isinstance(x.get("id"), int) and x.get("id") in chart_object_ids:
                    dep = True
                    break
                if isinstance(x, int) and x in chart_object_ids:
                    dep = True
                    break
        if not dep and isinstance(p.get("slices"), list):
            for x in p.get("slices"):
                if isinstance(x, int) and x in chart_object_ids:
                    dep = True
                    break
                if isinstance(x, dict) and isinstance(x.get("slice_id"), int) and x.get("slice_id") in chart_object_ids:
                    dep = True
                    break
        if not dep and isinstance(p.get("datasets"), list):
            for x in p.get("datasets"):
                if isinstance(x, int) and x in dataset_object_ids:
                    dep = True
                    break
                if isinstance(x, dict) and isinstance(x.get("id"), int) and x.get("id") in dataset_object_ids:
                    dep = True
                    break
        if dep:
            related_dashboards.append(d)

    def _ref(a):
        return {
            "id": a.get("id"),
            "superset_object_id": a.get("superset_object_id"),
            "name": a.get("name"),
            "slug": a.get("slug"),
            "status": a.get("status"),
            "last_synced_at": a.get("last_synced_at"),
        }

    resp = {
        "database": _ref(db_asset),
        "counts": {
            "datasets": len(datasets),
            "charts": len(charts),
            "dashboards": len(related_dashboards),
        },
        "datasets": [_ref(x) for x in sorted(datasets, key=lambda r: (r.get("name") or "", r.get("superset_object_id") or 0))],
        "charts": [_ref(x) for x in sorted(charts, key=lambda r: (r.get("name") or "", r.get("superset_object_id") or 0))],
        "dashboards": [_ref(x) for x in sorted(related_dashboards, key=lambda r: (r.get("name") or "", r.get("superset_object_id") or 0))],
        "meta": {"superset_instance_id": instance_id}
    }

    _log("ok", credential_id=chosen_session.get("id"), superset_instance_id=instance_id, started=started, meta={"database_id": database_id})
    return resp

