        _log("error", error_code="UNAUTHORIZED", error_message="No authenticated Superset session available", started=started)
        return _err("UNAUTHORIZED", "No authenticated Superset session available")

    instance_id = chosen["id"]

    # Ensure DB exists in cache (NOT_FOUND if not)
    db_assets = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "database"
        and a.get("superset_object_id") == database_id
        and a.get("status") != "deleted"
    ]
    if not db_assets:
        _log("error", credential_id=chosen_session.get("id"), superset_instance_id=instance_id, error_code="NOT_FOUND",
             error_message="Database not found", started=started, meta={"database_id": database_id})
        return _err("NOT_FOUND", "Database not found", database_id=database_id)

    db_asset = sorted(db_assets, key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))[0]

    # Offline "validation": basic checks + attach result to payload and last_synced_at (allowed by business rules).
    s = sql.strip()
    lowered = s.lower()

    valid = True
    errors = []
    warnings = []

    # Extremely basic heuristics similar to a linter, not a parser.
    if len(s) > 1_000_000:
        valid = False
        errors.append({"message": "SQL too large", "code": "SQL_TOO_LARGE"})
    if "\x00" in s:
        valid = False
        errors.append({"message": "SQL contains NUL byte", "code": "INVALID_CHAR"})
    if re.search(r";\s*;\s*", s):
        warnings.append({"message": "SQL contains multiple statement separators", "code": "MULTI_STATEMENT"})
    if re.search(r"\bdrop\b|\btruncate\b", lowered):
        warnings.append({"message": "SQL contains potentially destructive statements", "code": "DESTRUCTIVE_STATEMENT"})
    if not re.search(r"\bselect\b|\bwith\b|\binsert\b|\bupdate\b|\bdelete\b|\bcreate\b|\balter\b", lowered):
        warnings.append({"message": "SQL does not appear to contain a standard statement keyword", "code": "UNKNOWN_STATEMENT"})

    # Persist attachment to database asset payload (do not create new assets)
    now = _now()
    updated = False
    for a in assets:
        if isinstance(a, dict) and a.get("id") == db_asset.get("id"):
            payload = a.get("payload")
            if not isinstance(payload, dict):
                payload = {}
            payload["last_sql_validation"] = {
                "validated_at": now,
                "database_id": database_id,
                "valid": valid,
                "errors": errors,
                "warnings": warnings,
            }
            a["payload"] = payload
            a["last_synced_at"] = now
            a["updated_at"] = now
            updated = True
            break
    if updated:
        _save("superset_assets.json", assets)

    resp = {
        "database_id": database_id,
        "valid": valid,
        "errors": errors,
        "warnings": warnings,
        "meta": {"superset_instance_id": instance_id}
    }

    _log("ok", credential_id=chosen_session.get("id"), superset_instance_id=instance_id, started=started,
         meta={"database_id": database_id, "valid": valid})
    return resp

def superset_database_validate_parameters(parameters, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status, credential_id=None, superset_instance_id=None, error_code=None, error_message=None, meta=None, started=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                latency_ms = None
                if started is not None:
                    latency_ms = int((time.time() - started) * 1000)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                    "endpoint": "superset_database_validate_parameters",
                    "timestamp": _now(),
                    "status": status,
                    "latency_ms": latency_ms,
                    "credential_id": credential_id,
                    "superset_instance_id": superset_instance_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "meta": meta or {}
                })
                _save(fname, logs)
                break

    started = time.time()

    if not isinstance(parameters, dict):
        _log("error", error_code="VALIDATION_ERROR", error_message="parameters must be an object", started=started)
        return _err("VALIDATION_ERROR", "parameters must be an object")

    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured", started=started)
        return _err("UNAUTHORIZED", "No active Superset instance configured")

    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))

    chosen = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst.get("id")
        if not inst_id:
            continue
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and s.get("token_type") == "bearer"]
        if cand:
            cand.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min, r.get("id") or ""))
            chosen = inst
            chosen_session = cand[-1]
            break

    if chosen is None:
        _log("error", error_code="UNAUTHORIZED", error_message="No authenticated Superset session available", started=started)
        return _err("UNAUTHORIZED", "No authenticated Superset session available")

    instance_id = chosen["id"]

    # Offline validation: check presence/types of typical fields; do NOT persist new assets.
    # Also redact likely secrets in echoes.
    errors = []
    warnings = []

    if not parameters:
        errors.append({"field": None, "message": "parameters cannot be empty", "code": "EMPTY_PARAMETERS"})

    # Accept either sqlalchemy_uri or discrete connection fields.
    has_uri = isinstance(parameters.get("sqlalchemy_uri"), str) and parameters.get("sqlalchemy_uri").strip() != ""
    has_discrete = any(k in parameters for k in ("host", "port", "username", "password", "database", "dbname", "engine", "drivername"))

    if not has_uri and not has_discrete:
        warnings.append({"message": "No sqlalchemy_uri or discrete connection fields found; unable to fully validate", "code": "INSUFFICIENT_FIELDS"})

    port = parameters.get("port")
    if port is not None and not isinstance(port, int):
        errors.append({"field": "port", "message": "port must be an integer", "code": "INVALID_TYPE"})
    if isinstance(port, int) and not (1 <= port <= 65535):
        errors.append({"field": "port", "message": "port must be between 1 and 65535", "code": "OUT_OF_RANGE"})

    # Basic URI shape
    if has_uri:
        uri = parameters.get("sqlalchemy_uri").strip()
        if "://" not in uri:
            errors.append({"field": "sqlalchemy_uri", "message": "sqlalchemy_uri must include scheme (e.g. postgresql://)", "code": "INVALID_URI"})
        if len(uri) > 10000:
            errors.append({"field": "sqlalchemy_uri", "message": "sqlalchemy_uri too long", "code": "URI_TOO_LONG"})

    # Redact sensitive echo
    redacted = {}
    for k, v in parameters.items():
        if k.lower() in ("password", "pass", "secret", "token", "access_token", "refresh_token"):
            redacted[k] = "***redacted***"
        elif k.lower() in ("sqlalchemy_uri", "uri", "connection_string"):
            # avoid leaking credentials if embedded
            if isinstance(v, str):
                redacted[k] = v.split("@")[-1] if "@" in v and "://" in v else "***redacted***"
            else:
                redacted[k] = "***redacted***"
        else:
            redacted[k] = v

    valid = len(errors) == 0

    resp = {
        "valid": valid,
        "errors": errors,
        "warnings": warnings,
        "echo": redacted,
        "meta": {"superset_instance_id": instance_id}
    }

    _log("ok" if valid else "error", credential_id=chosen_session.get("id"), superset_instance_id=instance_id, started=started,
         error_code=None if valid else "VALIDATION_ERROR",
         error_message=None if valid else "Parameter validation failed",
         meta={"valid": valid, "error_count": len(errors)})
    # Note: endpoint returns validation outcome; does not raise on invalid parameters per tool description,
    # but does raise VALIDATION_ERROR when parameters missing/not object (already handled).
    return resp

