def superset_dataset_get_by_id(dataset_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_dataset_get_by_id"
    credential_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        }
        if error is not None:
            row["error"] = error
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(dataset_id, int):
        e = _err("VALIDATION_ERROR", "dataset_id must be an integer", field="dataset_id")
        _log("error", e["error"])
        return e
    if dataset_id <= 0:
        e = _err("VALIDATION_ERROR", "dataset_id must be a positive integer", field="dataset_id")
        _log("error", e["error"])
        return e

    instances = _load("superset_instances.json")
    active = [r for r in instances if r.get("status") == "active"]
    if not active:
        e = _err("UNAUTHORIZED", "No active Superset instance is configured")
        _log("error", e["error"])
        return e

    def _parse_dt(s):
        if not s or not isinstance(s, str): 
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))
    instance = active[0]
    instance_id = instance.get("id")

    # Find dataset asset
    assets = _load("superset_assets.json")
    matches = [
        a for a in assets
        if a.get("superset_instance_id") == instance_id
        and a.get("asset_type") == "dataset"
        and a.get("superset_object_id") == dataset_id
    ]
    if not matches:
        e = _err("NOT_FOUND", f"No dataset found with id {dataset_id}", dataset_id=dataset_id)
        _log("error", e["error"], {"superset_instance_id": instance_id})
        return e

    # Prefer active, else stale, else deleted
    pref = {"active": 0, "stale": 1, "deleted": 2}
    matches.sort(key=lambda a: (pref.get(a.get("status"), 9), _parse_dt(a.get("updated_at")) or datetime.datetime.min), reverse=False)
    asset = matches[0]

    # If locally deleted, treat as not found
    if asset.get("status") == "deleted":
        e = _err("NOT_FOUND", f"No dataset found with id {dataset_id}", dataset_id=dataset_id)
        _log("error", e["error"], {"superset_instance_id": instance_id})
        return e

    # "Fetches full details" - offline datastore: return cached payload as-is and update last_synced_at best-effort.
    now = _now()
    changed = False
    if asset.get("last_synced_at") != now:
        asset["last_synced_at"] = now
        asset["updated_at"] = now
        changed = True
    if changed:
        # write-through
        for i, a in enumerate(assets):
            if a.get("id") == asset.get("id"):
                assets[i] = asset
                break
        _save("superset_assets.json", assets)

    resp = {
        "dataset": asset,
        "superset_instance": {
            "id": instance.get("id"),
            "base_url": instance.get("base_url"),
            "api_prefix": instance.get("api_prefix"),
            "verify_tls": instance.get("verify_tls"),
            "default_timeout_ms": instance.get("default_timeout_ms"),
            "status": instance.get("status"),
        },
    }
    _log("ok", None, {"superset_instance_id": instance_id})
    return resp

