def superset_sqllab_format_sql(sql, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # usage/audit log collection (local to this implementation)
    def _log(status, superset_instance_id=None, auth_session_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "superset_integration",
            "endpoint": "superset_sqllab_format_sql",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "superset_instance_id": superset_instance_id,
            "auth_session_id": auth_session_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(sql, str) or not sql.strip():
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sql must be a non-empty string")

    # Resolve an active instance + usable session (ambient auth)
    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")

    active_instances = [i for i in instances if i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    # deterministically choose lowest created_at
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        sid = inst.get("id")
        # session prerequisites: status authenticated and access_token present
        cand = [s for s in sessions if s.get("superset_instance_id") == sid and s.get("status") == "authenticated" and isinstance(s.get("access_token"), str) and s.get("access_token")]
        # deterministically pick lowest created_at
        cand.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authenticated Superset session is available")

    # "Real" formatting endpoint is remote; offline implementation formats deterministically.
    # A simple SQL formatter: normalize whitespace, uppercase common keywords, newline before major clauses.
    keywords = [
        "select", "from", "where", "group by", "order by", "having", "limit", "join", "left join", "right join",
        "inner join", "outer join", "full join", "cross join", "union", "union all", "with", "on", "and", "or"
    ]
    # protect quoted strings
    s = sql.strip()

    # collapse whitespace outside quotes
    out = []
    in_s = False
    in_d = False
    prev_space = False
    for ch in s:
        if ch == "'" and not in_d:
            in_s = not in_s
        elif ch == '"' and not in_s:
            in_d = not in_d
        if (in_s or in_d):
            out.append(ch)
            prev_space = False
        else:
            if ch.isspace():
                if not prev_space:
                    out.append(" ")
                    prev_space = True
            else:
                out.append(ch)
                prev_space = False
    s = "".join(out).strip()

    # uppercase keywords (longer phrases first)
    def _repl_kw(m):
        return m.group(0).upper()

    # add newlines before major clauses
    major = ["with", "select", "from", "where", "group by", "having", "order by", "limit", "union", "union all"]
    # uppercase keywords using regex word boundaries; handle multi-word
    for kw in sorted(keywords, key=lambda x: -len(x)):
        pattern = r"(?i)\b" + re.escape(kw) + r"\b"
        s = re.sub(pattern, _repl_kw, s)

    # newlines before major clauses (case-insensitive now uppercased)
    for clause in ["WITH", "SELECT", "FROM", "WHERE", "GROUP BY", "HAVING", "ORDER BY", "LIMIT", "UNION ALL", "UNION"]:
        s = re.sub(r"\s+" + re.escape(clause) + r"\b", "\n" + clause, s)

    formatted = s.strip()

    # touch session validation fields as a best-effort "used endpoint" signal
    # (no /me call possible offline; do not change last_validation_ok)
    for idx, sess in enumerate(sessions):
        if sess.get("id") == chosen_session.get("id"):
            sess["updated_at"] = now
            sessions[idx] = sess
            break
    _save("auth_sessions.json", sessions)

    resp = {
        "formatted_sql": formatted,
        "superset_instance_id": chosen_instance.get("id"),
    }
    _log("ok", superset_instance_id=chosen_instance.get("id"), auth_session_id=chosen_session.get("id"))
    return resp

def superset_sqllab_get_results(key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, superset_instance_id=None, auth_session_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "superset_integration",
            "endpoint": "superset_sqllab_get_results",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "superset_instance_id": superset_instance_id,
            "auth_session_id": auth_session_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(key, str) or not key.strip():
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    queries = _load("sql_lab_queries.json")

    active_instances = [i for i in instances if i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        sid = inst.get("id")
        cand = [s for s in sessions if s.get("superset_instance_id") == sid and s.get("status") == "authenticated" and isinstance(s.get("access_token"), str) and s.get("access_token")]
        cand.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authenticated Superset session is available")

    sid = chosen_instance.get("id")

    # Lookup by (superset_instance_id, result_key)
    q = None
    for row in queries:
        if row.get("superset_instance_id") == sid and row.get("result_key") == key:
            q = row
            break

    if q is None:
        # Rule: may create a new row with status='success' and only result_key populated,
        # but must still require known superset_instance_id context (we have it).
        # However tool description says NOT_FOUND if result key does not exist.
        # Prefer NOT_FOUND unless there is evidence this key is known; no remote call possible, so NOT_FOUND.
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Result key does not exist")

    # If we have cached results_preview, return it; otherwise NOT_FOUND (can't fetch remotely offline)
    payload = q.get("results_preview")
    if payload is None:
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No cached results available for this result key")

    # touch updated_at
    changed = False
    for i, row in enumerate(queries):
        if row.get("id") == q.get("id"):
            if row.get("updated_at") != now:
                row["updated_at"] = now
                queries[i] = row
                changed = True
            break
    if changed:
        _save("sql_lab_queries.json", queries)

    _log("ok", superset_instance_id=sid, auth_session_id=chosen_session.get("id"))
    return {
        "key": key,
        "superset_instance_id": sid,
        "result": payload
    }

def superset_sqllab_estimate_query_cost(database_id, sql, schema=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, superset_instance_id=None, auth_session_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "superset_integration",
            "endpoint": "superset_sqllab_estimate_query_cost",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "superset_instance_id": superset_instance_id,
            "auth_session_id": auth_session_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(database_id, int) or database_id <= 0:
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "database_id must be a positive integer")
    if not isinstance(sql, str) or not sql.strip():
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sql must be a non-empty string")
    if schema is not None and (not isinstance(schema, str) or not schema.strip()):
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "schema must be a non-empty string when provided")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    assets = _load("superset_assets.json")

    active_instances = [i for i in instances if i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        sid = inst.get("id")
        cand = [s for s in sessions if s.get("superset_instance_id") == sid and s.get("status") == "authenticated" and isinstance(s.get("access_token"), str) and s.get("access_token")]
        cand.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authenticated Superset session is available")

    sid = chosen_instance.get("id")

    # Find database asset for this instance with superset_object_id == database_id
    db_asset = None
    for a in assets:
        if a.get("superset_instance_id") == sid and a.get("asset_type") == "database" and a.get("superset_object_id") == database_id:
            db_asset = a
            break
    if db_asset is None:
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "database_id does not reference a known database asset in this instance")

    # Offline "estimate": basic heuristics + persist into asset payload as cached info
    sql_txt = sql.strip()
    # crude table count estimate: count FROM and JOIN occurrences
    froms = len(re.findall(r"(?i)\bFROM\b", sql_txt))
    joins = len(re.findall(r"(?i)\bJOIN\b", sql_txt))
    has_limit = bool(re.search(r"(?i)\bLIMIT\b\s+\d+", sql_txt))
    # complexity score
    score = 1 + joins * 2 + max(0, froms - 1)
    if re.search(r"(?i)\bGROUP\s+BY\b", sql_txt):
        score += 2
    if re.search(r"(?i)\bORDER\s+BY\b", sql_txt):
        score += 1
    if re.search(r"(?i)\bUNION\b", sql_txt):
        score += 3
    if re.search(r"(?i)\bWITH\b", sql_txt):
        score += 1
    if has_limit:
        score = max(1, score - 1)

    estimate = {
        "engine": (db_asset.get("payload") or {}).get("backend") if isinstance(db_asset.get("payload"), dict) else None,
        "schema": schema.strip() if isinstance(schema, str) else None,
        "estimated_complexity_score": score,
        "estimated_joins": joins,
        "estimated_sources": max(froms, 1),
        "note": "Offline estimate (heuristic). Superset backend estimate not available in this environment."
    }

    # Attach to database asset payload + update last_synced_at
    changed = False
    for i, a in enumerate(assets):
        if a.get("id") == db_asset.get("id"):
            payload = a.get("payload")
            if payload is None or not isinstance(payload, dict):
                payload = {}
            payload["last_cost_estimate"] = estimate
            payload["last_cost_estimate_sql_fingerprint"] = str(abs(hash(sql_txt)) % (10**12))
            payload["last_cost_estimate_at"] = now
            a["payload"] = payload
            a["last_synced_at"] = now
            a["updated_at"] = now
            assets[i] = a
            changed = True
            break
    if changed:
        _save("superset_assets.json", assets)

    _log("ok", superset_instance_id=sid, auth_session_id=chosen_session.get("id"))
    return {
        "superset_instance_id": sid,
        "database_id": database_id,
        "estimate": estimate
    }

def superset_sqllab_export_query_results(client_id, **_extra):
    import json, os, datetime, time, csv, io

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, superset_instance_id=None, auth_session_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "superset_integration",
            "endpoint": "superset_sqllab_export_query_results",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "superset_instance_id": superset_instance_id,
            "auth_session_id": auth_session_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(client_id, str) or not client_id.strip():
        _log("error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    queries = _load("sql_lab_queries.json")

    active_instances = [i for i in instances if i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    active_instances.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        sid = inst.get("id")
        cand = [s for s in sessions if s.get("superset_instance_id") == sid and s.get("status") == "authenticated" and isinstance(s.get("access_token"), str) and s.get("access_token")]
        cand.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authenticated Superset session is available")

    sid = chosen_instance.get("id")

    # Must lookup sql_lab_queries by client_id; if not found return NOT_FOUND
    q = None
    for row in queries:
        if row.get("superset_instance_id") == sid and row.get("client_id") == client_id:
            q = row
            break
    if q is None:
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No SQL Lab query found for this client_id")

    preview = q.get("results_preview")
    if preview is None or not isinstance(preview, dict):
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No cached results to export for this client_id")

    columns = preview.get("columns")
    rows = preview.get("rows")
    if not isinstance(columns, list) or not isinstance(rows, list):
        _log("error", superset_instance_id=sid, auth_session_id=chosen_session.get("id"), detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Cached results_preview is missing columns/rows in an exportable format")

    # columns might be list of dicts with 'name' or list of strings
    header = []
    for c in columns:
        if isinstance(c, str):
            header.append(c)
        elif isinstance(c, dict) and isinstance(c.get("name"), str):
            header.append(c.get("name"))
        else:
            header.append(str(c))

    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(header)
    for r in rows:
        if isinstance(r, dict):
            w.writerow([r.get(h) for h in header])
        elif isinstance(r, (list, tuple)):
            w.writerow(list(r))
        else:
            w.writerow([r])

    csv_text = buf.getvalue()

    _log("ok", superset_instance_id=sid, auth_session_id=chosen_session.get("id"))
    return {
        "superset_instance_id": sid,
        "client_id": client_id,
        "content_type": "text/csv; charset=utf-8",
        "filename": f"sqllab_{client_id}.csv",
        "data": csv_text
    }

def superset_sqllab_get_bootstrap_data(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # simple request log if present
    def _log(status, superset_instance_id=None, auth_session_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "superset_sqllab_get_bootstrap_data",
                "superset_instance_id": superset_instance_id,
                "auth_session_id": auth_session_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    assets = _load("superset_assets.json")

    # Find a working authenticated session on an active instance, deterministically by instance created_at then session created_at
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and isinstance(i.get("id"), str)]
    def _ts(v):
        return v if isinstance(v, str) else ""
    active_instances.sort(key=lambda r: (_ts(r.get("created_at")), r.get("id")))
    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst["id"]
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and (s.get("access_token") or s.get("refresh_token"))]
        cand.sort(key=lambda r: (_ts(r.get("created_at")), r.get("id")))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No Superset session is available to access SQL Lab bootstrap data.")

    inst_id = chosen_instance["id"]
    sess_id = chosen_session.get("id")

    # "Real" bootstrap would come from Superset; offline we return cached configuration-like data from local store.
    # Include databases from cached assets.
    db_assets = [a for a in assets if isinstance(a, dict) and a.get("superset_instance_id") == inst_id and a.get("asset_type") == "database" and a.get("status") in ("active", "stale")]
    # deterministic ordering
    db_assets.sort(key=lambda r: (r.get("superset_object_id") if isinstance(r.get("superset_object_id"), int) else 10**18, r.get("id") or ""))

    databases = []
    for a in db_assets:
        payload = a.get("payload") if isinstance(a.get("payload"), dict) else {}
        databases.append({
            "id": a.get("superset_object_id"),
            "database_name": a.get("name"),
            "allow_run_async": payload.get("allow_run_async"),
            "expose_in_sqllab": payload.get("expose_in_sqllab"),
            "allow_ctas": payload.get("allow_ctas"),
            "allow_cvas": payload.get("allow_cvas"),
            "allow_dml": payload.get("allow_dml"),
        })

