def superset_query_stop(client_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, superset_instance_id=None, auth_session_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "superset_query_stop",
                "superset_instance_id": superset_instance_id,
                "auth_session_id": auth_session_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)

    if not isinstance(client_id, str) or not client_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`client_id` must be a non-empty string.", field="client_id")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    queries = _load("sql_lab_queries.json")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and isinstance(i.get("id"), str)]
    active_instances.sort(key=lambda r: ((r.get("created_at") if isinstance(r.get("created_at"), str) else ""), r.get("id")))
    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst["id"]
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and (s.get("access_token") or s.get("refresh_token"))]
        cand.sort(key=lambda r: ((r.get("created_at") if isinstance(r.get("created_at"), str) else ""), r.get("id") or ""))
        if cand:
            chosen_instance = inst
            chosen_session = cand[0]
            break

    if not chosen_instance or not chosen_session:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No Superset session is available to stop queries.")

    inst_id = chosen_instance["id"]
    sess_id = chosen_session.get("id")

    # Find query by client_id scoped to instance
    q = None
    for row in queries:
        if isinstance(row, dict) and row.get("superset_instance_id") == inst_id and row.get("client_id") == client_id:
            q = row
            break

    if not q:
        _log("error", superset_instance_id=inst_id, auth_session_id=sess_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No known query matches the provided `client_id`.", client_id=client_id)

    cur = q.get("status")
    if cur in ("queued", "running"):
        # legal transition to stopped
        q["status"] = "stopped"
        q["updated_at"] = now
        if not q.get("finished_at"):
            q["finished_at"] = now
        if q.get("started_at") and not isinstance(q.get("duration_ms"), int):
            # best-effort duration
            q["duration_ms"] = None
        _save("sql_lab_queries.json", queries)
        payload = {
            "client_id": client_id,
            "status": "stopped",
            "message": "Query stop requested."
        }
        _log("ok", superset_instance_id=inst_id, auth_session_id=sess_id)
        return {"data": payload}

    if cur == "stopped":
        # idempotent success with no additional changes
        payload = {
            "client_id": client_id,
            "status": "stopped",
            "message": "Query was already stopped."
        }
        _log("ok", superset_instance_id=inst_id, auth_session_id=sess_id)
        return {"data": payload}

    # finished statuses cannot be stopped
    if cur in ("success", "failed", "expired"):
        _log("error", superset_instance_id=inst_id, auth_session_id=sess_id, error_code="CONFLICT")
        return _err("CONFLICT", f"Query is already finished with status='{cur}' and cannot be stopped.", client_id=client_id, status=cur)

    # Unknown status in store -> treat as invalid transition
    _log("error", superset_instance_id=inst_id, auth_session_id=sess_id, error_code="INVALID_TRANSITION")
    return _err("INVALID_TRANSITION", "Query status does not allow stopping.", client_id=client_id, status=cur)

def superset_query_list(page=None, page_size=None, order_column=None, order_direction=None, search=None, status=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_query_list"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # best-effort request logging (schema not provided); do not fail if absent/unwritable
    def _log(status_code, credential_id=None, error_code=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                logs.append(row)
                _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be a positive integer (1-based).", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500.", field="page_size")
    if order_direction is not None:
        if not isinstance(order_direction, str) or order_direction not in ("asc", "desc"):
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_direction must be 'asc' or 'desc'.", field="order_direction")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "success", "failed", "stopped", "expired"):
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status filter value.", field="status")
    if search is not None and not isinstance(search, str):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")
    if order_column is not None and not isinstance(order_column, str):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_column must be a string.", field="order_column")

    # Ambient auth: find a workable authenticated session for an active instance
    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst.get("id")
        if not inst_id:
            continue
        candidate_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token")]
        if candidate_sessions:
            # deterministically choose one
            candidate_sessions.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))
            chosen_instance = inst
            chosen_session = candidate_sessions[0]
            break
    if not chosen_session:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated Superset session is available.")

    # We cannot call Superset offline; serve from local cache (sql_lab_queries)
    queries = _load("sql_lab_queries.json")
    rows = [q for q in queries if isinstance(q, dict) and q.get("superset_instance_id") == chosen_instance.get("id")]

    # Filters
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if search:
        s = search.strip().lower()
        if s:
            def _hay(r):
                return " ".join([str(r.get("sql") or ""), str(r.get("error_message") or ""), str(r.get("client_id") or ""), str(r.get("result_key") or ""), str(r.get("id") or ""), str(r.get("superset_query_id") or "")]).lower()
            rows = [r for r in rows if s in _hay(r)]

    # Sort
    allowed_order_columns = {
        "created_at", "updated_at", "started_at", "finished_at",
        "duration_ms", "row_count", "status", "id", "superset_query_id"
    }
    if order_column is None:
        order_column = "created_at"
    if order_column not in allowed_order_columns:
        _log(400, chosen_session.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported order_column.", field="order_column", allowed=sorted(list(allowed_order_columns)))
    direction = order_direction or "desc"

    def _sort_key(r):
        v = r.get(order_column)
        if order_column.endswith("_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime.min
        if isinstance(v, (int, float)):
            return v
        if v is None:
            return ""
        return str(v)

    rows.sort(key=_sort_key, reverse=(direction == "desc"))

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Mark records stale rather than deleting anything missing from a page of results:
    # (No Superset fetch here, so no stale marking based on remote.)
    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "superset_instance_id": chosen_instance.get("id"),
        }
    }
    _log(200, chosen_session.get("id"), None)
    return resp

