    queries = _load("sql_lab_queries.json")
    rows = [q for q in queries if isinstance(q, dict) and q.get("superset_instance_id") == chosen_instance.get("id")]

    def _activity_item(q):
        return {
            "type": "sql_query",
            "sql_lab_query_id": q.get("id"),
            "superset_query_id": q.get("superset_query_id"),
            "status": q.get("status"),
            "created_at": q.get("created_at"),
            "started_at": q.get("started_at"),
            "finished_at": q.get("finished_at"),
