            "row_count": q.get("row_count"),
            "client_id": q.get("client_id"),
            "result_key": q.get("result_key"),
        }

    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or ""), reverse=True)
    activity = [_activity_item(r) for r in rows]

    total = len(activity)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = activity[start:end]
    has_more = end < total

    _log(200, chosen_session.get("id"), None)
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "superset_instance_id": chosen_instance.get("id"),
