    }

def superset_user_get_current(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_user_get_current"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                logs.append(row)
                _save("request_logs.json", logs)
        except Exception:
            pass

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))

    chosen_instance = None
    chosen_session = None
    for inst in active_instances:
        inst_id = inst.get("id")
        if not inst_id:
            continue
        cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id and s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token")]
        if cand:
            cand.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))
            chosen_instance = inst
            chosen_session = cand[0]
            break
    if not chosen_session:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated Superset session is available.")

    # Offline/local behavior: return what we can from auth_sessions + instance configuration.
    # Also update last_validated_at/last_validation_ok best-effort (since we cannot call /me here).
    sess_id = chosen_session.get("id")
    updated = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sess_id:
            s["last_validated_at"] = now
            # In real backend this reflects /api/v1/me; here, having an access_token is the best available signal.
            s["last_validation_ok"] = True if s.get("access_token") else False
            s["updated_at"] = now
            updated = True
            break
    if updated:
        try:
            _save("auth_sessions.json", sessions)
        except Exception:
            pass

    profile = {
        "superset_instance": {
            "id": chosen_instance.get("id"),
            "base_url": chosen_instance.get("base_url"),
            "display_name": chosen_instance.get("display_name"),
            "api_prefix": chosen_instance.get("api_prefix"),
        },
        "session": {
            "id": chosen_session.get("id"),
            "username": chosen_session.get("username"),
            "token_type": chosen_session.get("token_type"),
            "status": chosen_session.get("status"),
            "access_token_expires_at": chosen_session.get("access_token_expires_at"),
            "last_validated_at": now,
            "last_validation_ok": True if chosen_session.get("access_token") else False,
        }
    }

    _log(200, chosen_session.get("id"), None)
    return {"data": profile}

def superset_user_get_roles(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request log enforcement: if a request log exists, record and enforce simple rate limit.
    # (Schema does not declare a request-log collection; thus no logging enforced.)
    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
    except Exception as e:
        return _err("UPSTREAM_ERROR", "Datastore unavailable", detail=str(e))

    # Select deterministic active instance: lowest created_at then id.
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance is configured")

    def _ts(v):
        if not v:
            return ""
        return str(v)

    active_instances.sort(key=lambda r: (_ts(r.get("created_at")), str(r.get("id"))))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Find a usable authenticated session for that instance.
    inst_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id]
    usable = []
    for s in inst_sessions:
        if s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token"):
            usable.append(s)
    if not usable:
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active instance")

    # Deterministic: choose most recently updated authenticated session, then created_at, then id.
    usable.sort(key=lambda r: (_ts(r.get("updated_at")), _ts(r.get("created_at")), str(r.get("id"))), reverse=True)
    sess = usable[0]

    # Offline server: emulate /api/v1/me/roles by returning local placeholder derived from session/instance.
    # Also update validation markers per business rule: "must call /api/v1/me and then update..."
    # We treat presence of access_token as validation ok.
    # Update session fields.
    changed = False
    for s in sessions:
        if s.get("id") == sess.get("id"):
            s["last_validated_at"] = now
            s["last_validation_ok"] = True
            # Do not change status; already authenticated.
            s["last_error_code"] = None
            s["last_error_message"] = None
            s["updated_at"] = now
            changed = True
            break
    if changed:
        try:
            _save("auth_sessions.json", sessions)
        except Exception as e:
            return _err("UPSTREAM_ERROR", "Failed to persist auth session validation state", detail=str(e))

    # Return roles payload "as provided by Superset": best-effort synthesized.
    # If a username exists, include it; otherwise anonymous.
    username = sess.get("username") or None
    roles = [
        {"id": 1, "name": "Gamma"},
    ]
    if username:
        roles.append({"id": 2, "name": "Public"})
    else:
        roles = [{"id": 2, "name": "Public"}]

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "instance": {
            "id": inst_id,
            "base_url": inst.get("base_url"),
            "api_prefix": inst.get("api_prefix"),
        },
        "session": {
            "id": sess.get("id"),
            "username": username,
            "token_type": sess.get("token_type"),
            "last_validated_at": now,
        },
        "result": roles,
        "meta": {"latency_ms": latency_ms},
    }

def superset_tag_list(page=None, page_size=None, order_column=None, order_direction=None, search=None, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page <= 0:
        return _err("VALIDATION_ERROR", "page must be a positive integer")
    if not isinstance(page_size, int) or page_size <= 0:
        return _err("VALIDATION_ERROR", "page_size must be a positive integer")
    if order_direction is not None and order_direction not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order_direction must be one of: asc, desc")
    if order_column is not None and not isinstance(order_column, str):
        return _err("VALIDATION_ERROR", "order_column must be a string")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string")

    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
        assets = _load("superset_assets.json")
    except Exception as e:
        return _err("UPSTREAM_ERROR", "Datastore unavailable", detail=str(e))

    # Select deterministic active instance
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance is configured")

    def _ts(v):
        if not v:
            return ""
        return str(v)

    active_instances.sort(key=lambda r: (_ts(r.get("created_at")), str(r.get("id"))))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Require authenticated session
    inst_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id]
    has_token = any(s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token") for s in inst_sessions)
    if not has_token:
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active instance")

    # List tag assets from local cache as stand-in for Superset /api/v1/tag/
    rows = [a for a in assets if isinstance(a, dict) and a.get("superset_instance_id") == inst_id and a.get("asset_type") == "tag" and a.get("status") != "deleted"]

    # Apply search
    if search:
        s = search.casefold()
        def _match(r):
            name = (r.get("name") or "")
            slug = (r.get("slug") or "")
            key = (r.get("superset_key") or "")
            return (s in str(name).casefold()) or (s in str(slug).casefold()) or (s in str(key).casefold())
        rows = [r for r in rows if _match(r)]

    # Sorting
    col = order_column or "name"
    reverse = (order_direction == "desc")
    def _k(r):
        v = r.get(col)
        if v is None:
            # push nulls last for asc, first for desc
            return (1, "")
        return (0, str(v).casefold() if isinstance(v, str) else v)
    try:
        rows.sort(key=_k, reverse=reverse)
    except TypeError:
        # Fallback deterministic
        rows.sort(key=lambda r: str(r.get("id")), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]

    # Convert to Superset-like tag objects; include "id" as numeric superset_object_id when present.
    result = []
    for r in page_rows:
        result.append({
            "id": r.get("superset_object_id"),
            "name": r.get("name"),
            "created_on": r.get("created_at"),
            "changed_on": r.get("updated_at"),
            "slug": r.get("slug"),
            "payload": r.get("payload"),
        })

    # Superset-style pagination metadata (best effort)
    page_count = int(math.ceil(total / float(page_size))) if page_size else 0
    has_more = end < total
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "result": result,
        "count": total,
        "page": page,
        "page_size": page_size,
        "pagination": {
            "total": total,
            "page": page,
            "page_size": page_size,
            "page_count": page_count,
            "has_more": has_more,
        },
        "meta": {
            "instance_id": inst_id,
            "latency_ms": latency_ms,
            "as_of": now,
        },
    }

def superset_tag_create(name, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name is required and must be a non-blank string")
    tag_name = name.strip()

    try:
        instances = _load("superset_instances.json")
        sessions = _load("auth_sessions.json")
        assets = _load("superset_assets.json")
    except Exception as e:
        return _err("UPSTREAM_ERROR", "Datastore unavailable", detail=str(e))

    # Select deterministic active instance
    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active"]
    if not active_instances:
        return _err("UNAUTHORIZED", "No active Superset instance is configured")

    def _ts(v):
        if not v:
            return ""
        return str(v)

    active_instances.sort(key=lambda r: (_ts(r.get("created_at")), str(r.get("id"))))
    inst = active_instances[0]
    inst_id = inst.get("id")

    # Require authenticated session
    inst_sessions = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == inst_id]
    has_token = any(s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token") for s in inst_sessions)
    if not has_token:
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active instance")

    # Uniqueness: tags are unique by (instance, asset_type, superset_object_id) but name uniqueness enforced by Superset.
    # We treat duplicate name among non-deleted tag assets as conflict (case-insensitive).
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != inst_id or a.get("asset_type") != "tag":
            continue
        if a.get("status") == "deleted":
            continue
        if isinstance(a.get("name"), str) and a["name"].strip().casefold() == tag_name.casefold():
            return _err("CONFLICT", "Tag with the same name already exists")

    # Create new "Superset" tag id (numeric) deterministically: max+1 within instance tags.
    max_id = 0
    for a in assets:
        if isinstance(a, dict) and a.get("superset_instance_id") == inst_id and a.get("asset_type") == "tag":
            soid = a.get("superset_object_id")
            if isinstance(soid, int) and soid > max_id:
                max_id = soid
    superset_object_id = max_id + 1

    asset_id = "ssa_" + uuid.uuid4().hex
    new_asset = {
        "id": asset_id,
        "superset_instance_id": inst_id,
        "asset_type": "tag",
        "superset_object_id": superset_object_id,
        "superset_key": None,
        "name": tag_name,
        "slug": None,
        "database_asset_id": None,
        "dataset_asset_id": None,
        "schema_name": None,
        "table_name": None,
        "datasource_type": None,
        "viz_type": None,
        "payload": None,
        "owners": None,
        "status": "active",
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }

    assets.append(new_asset)
    try:
        _save("superset_assets.json", assets)
    except Exception as e:
        return _err("UPSTREAM_ERROR", "Failed to persist created tag", detail=str(e))

    latency_ms = int((time.time() - t0) * 1000)
    # Return Superset-like created record
    return {
        "result": {
            "id": superset_object_id,
            "name": tag_name,
            "created_on": now,
            "changed_on": now,
        },
        "meta": {
            "instance_id": inst_id,
            "asset_id": asset_id,
            "latency_ms": latency_ms,
        },
    }

