        rule = None
        for r in limits:
            if isinstance(r, dict) and r.get("service") in (None, "superset_integration") and r.get("status", "active") == "active":
                rule = r
                break
        if not rule:
            return None
        per_min = rule.get("requests_per_minute")
        per_day = rule.get("requests_per_day")
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if isinstance(per_min, int) and per_min >= 0:
            cutoff = (now - datetime.timedelta(seconds=60))
            c = 0
            for e in logs:
                ts = e.get("timestamp")
                if not isinstance(ts, str): 
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(per_day, int) and per_day >= 0:
            cutoff = (now - datetime.timedelta(days=1))
            c = 0
            for e in logs:
                ts = e.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= per_day:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    # Validate inputs
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        out = _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        out = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500", field="page_size")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    allowed_types = {"chart", "dashboard", "dataset", "database"}
    if object_type is not None and (not isinstance(object_type, str) or object_type not in allowed_types):
        out = _err("VALIDATION_ERROR", "object_type must be one of: chart, dashboard, dataset, database", field="object_type")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    # Resolve an active instance and an authenticated session for it (ambient auth)
    instances = _load("superset_instances.json")
    active = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    if not active:
        out = _err("UNAUTHORIZED", "No active Superset instance is configured")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    active.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    instance = active[0]
    instance_id = instance.get("id")

    sessions = _load("auth_sessions.json")
    usable = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("superset_instance_id") != instance_id:
            continue
        if s.get("status") == "authenticated":
            usable.append(s)
    if not usable:
        out = _err("UNAUTHORIZED", "No authenticated Superset session available for the active instance")
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    # Build grouped view from local cache (tag_assignments + superset_assets)
    assets = _load("superset_assets.json")
    assigns = _load("tag_assignments.json")

    assets_by_id = {a.get("id"): a for a in assets if isinstance(a, dict) and isinstance(a.get("id"), str)}
    # tag assets for instance, active (not deleted)
    tag_assets = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != instance_id:
            continue
        if a.get("asset_type") == "tag" and a.get("status") != "deleted":
            # prefer object_id-based tags; but name may exist
            key = a.get("superset_object_id")
            if isinstance(key, int):
                tag_assets[key] = a

    # Group by tag -> object_type
    groups_map = {}  # (tag_id, object_type) -> group
    for ta in assigns:
        if not isinstance(ta, dict):
            continue
        if ta.get("superset_instance_id") != instance_id:
            continue
        if ta.get("status") != "active":
            continue
        ot = ta.get("object_type")
        if object_type is not None and ot != object_type:
            continue
        tag_asset = assets_by_id.get(ta.get("tag_asset_id"))
        obj_asset = assets_by_id.get(ta.get("object_asset_id"))
        if not tag_asset or not obj_asset:
            continue
        if tag_asset.get("asset_type") != "tag":
            continue
        if obj_asset.get("asset_type") not in allowed_types:
            continue
        if ot != obj_asset.get("asset_type"):
            continue
        if tag_asset.get("status") == "deleted":
            continue

        tag_superset_id = tag_asset.get("superset_object_id")
        tag_name = tag_asset.get("name")
        if not isinstance(tag_superset_id, int):
            # If tag has no numeric id, skip (cannot match Superset "grouped" response style reliably)
            continue

        key = (tag_superset_id, ot)
        g = groups_map.get(key)
        if not g:
            g = {
                "tag": {
                    "id": tag_superset_id,
                    "name": tag_name,
                },
                "object_type": ot,
                "objects": [],
            }
            groups_map[key] = g
        obj_entry = {
            "id": obj_asset.get("superset_object_id"),
            "name": obj_asset.get("name"),
            "slug": obj_asset.get("slug"),
        }
        g["objects"].append(obj_entry)

    groups = list(groups_map.values())
    # Deterministic ordering similar to backend: by tag name then object_type then tag id
    def _s(x):
        return (str((x.get("tag") or {}).get("name") or "").lower(), x.get("object_type") or "", int((x.get("tag") or {}).get("id") or 0))
    groups.sort(key=_s)

    total = len(groups)
    start = (page - 1) * page_size
    end = start + page_size
    page_groups = groups[start:end]
    has_more = end < total

    resp = {
        "result": page_groups,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
        },
        "superset_instance": {
            "id": instance_id,
            "base_url": instance.get("base_url"),
        },
    }
    _log("ok", superset_instance_id=instance_id)
    return resp

