        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    assets = _load("superset_assets.json")
    assigns = _load("tag_assignments.json")

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    # Resolve object asset
    obj_asset = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != instance_id:
            continue
        if a.get("asset_type") != object_type:
            continue
        if a.get("superset_object_id") == object_id:
            obj_asset = a
            break
    if not obj_asset or obj_asset.get("status") == "deleted":
        out = _err("NOT_FOUND", "Target object not found in local cache", object_type=object_type, object_id=object_id)
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    # Find or create tag asset by name (business rule)
    tag_asset = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != instance_id:
            continue
        if a.get("asset_type") != "tag":
            continue
        if isinstance(a.get("name"), str) and a.get("name").strip().lower() == tag_name.lower():
            tag_asset = a
            break

    now = _now

    if tag_asset:
        # Reactivate if previously deleted/stale
        if tag_asset.get("status") == "deleted":
            # deleted -> cannot transition per lifecycle; create a new tag asset instead (models re-created tag)
            tag_asset = None
        else:
            if tag_asset.get("status") in ("stale",):
                tag_asset["status"] = "active"
            tag_asset["name"] = tag_name
            tag_asset["updated_at"] = now

    if not tag_asset:
        # Create a local tag asset (no numeric superset_object_id known here)
        tag_asset = {
            "id": _new_id("sasset"),
            "superset_instance_id": instance_id,
            "asset_type": "tag",
            "superset_object_id": None,
            "superset_key": None,
            "name": tag_name,
            "slug": None,
            "database_asset_id": None,
            "dataset_asset_id": None,
            "schema_name": None,
            "table_name": None,
            "datasource_type": None,
            "viz_type": None,
