        assets.append(tag_asset)

    # Create or reactivate tag assignment, unique(instance, tag_asset_id, object_asset_id)
    existing = None
    for ta in assigns:
        if not isinstance(ta, dict):
            continue
        if ta.get("superset_instance_id") != instance_id:
            continue
        if ta.get("tag_asset_id") == tag_asset.get("id") and ta.get("object_asset_id") == obj_asset.get("id"):
            existing = ta
            break

    if existing:
        # removed -> active allowed, active -> active idempotent
        if existing.get("status") == "removed":
            existing["status"] = "active"
            existing["updated_at"] = now
        else:
            # idempotent
            existing["updated_at"] = now
        assignment = existing
    else:
        assignment = {
            "id": _new_id("tagasgn"),
            "superset_instance_id": instance_id,
            "tag_asset_id": tag_asset.get("id"),
            "object_asset_id": obj_asset.get("id"),
            "object_type": object_type,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        assigns.append(assignment)

    _save("superset_assets.json", assets)
    _save("tag_assignments.json", assigns)

    resp = {
        "result": {
            "tag_name": tag_name,
            "object_type": object_type,
            "object_id": object_id,
            "status": "active",
        },
        "local_cache": {
            "tag_asset": {
                "id": tag_asset.get("id"),
                "superset_object_id": tag_asset.get("superset_object_id"),
                "name": tag_asset.get("name"),
                "status": tag_asset.get("status"),
            },
            "assignment": {
                "id": assignment.get("id"),
                "status": assignment.get("status"),
            },
        },
        "superset_instance": {
            "id": instance_id,
            "base_url": instance.get("base_url"),
        },
    }
    _log("ok", superset_instance_id=instance_id, object_type=object_type, object_id=object_id)
    return resp

