    def _rate_limit_check():
        limits = _load("rate_limits.json")
        if not limits:
            return None
        rule = None
        for r in limits:
            if isinstance(r, dict) and r.get("service") in (None, "superset_integration") and r.get("status", "active") == "active":
                rule = r
                break
        if not rule:
            return None
        per_min = rule.get("requests_per_minute")
        per_day = rule.get("requests_per_day")
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if isinstance(per_min, int) and per_min >= 0:
            cutoff = (now - datetime.timedelta(seconds=60))
            c = 0
            for e in logs:
                ts = e.get("timestamp")
                if not isinstance(ts, str): 
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(per_day, int) and per_day >= 0:
            cutoff = (now - datetime.timedelta(days=1))
            c = 0
            for e in logs:
                ts = e.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= per_day:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    allowed_types = {"chart", "dashboard", "dataset", "database"}
    if not isinstance(object_type, str) or object_type not in allowed_types:
        out = _err("VALIDATION_ERROR", "object_type must be one of: chart, dashboard, dataset, database", field="object_type")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if not isinstance(object_id, int) or object_id <= 0:
        out = _err("VALIDATION_ERROR", "object_id must be a positive integer", field="object_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if not isinstance(tag_name, str) or not tag_name.strip():
        out = _err("VALIDATION_ERROR", "tag_name must be a non-empty string", field="tag_name")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    tag_name = tag_name.strip()

    instances = _load("superset_instances.json")
    active = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and isinstance(i.get("created_at"), str)]
    if not active:
        out = _err("UNAUTHORIZED", "No active Superset instance is configured")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    active.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    instance = active[0]
    instance_id = instance.get("id")

    sessions = _load("auth_sessions.json")
    if not any(isinstance(s, dict) and s.get("superset_instance_id") == instance_id and s.get("status") == "authenticated" for s in sessions):
        out = _err("UNAUTHORIZED", "No authenticated Superset session available for the active instance")
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    assets = _load("superset_assets.json")
    assigns = _load("tag_assignments.json")

    # Resolve object asset
    obj_asset = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != instance_id:
            continue
        if a.get("asset_type") != object_type:
            continue
        if a.get("superset_object_id") == object_id:
            obj_asset = a
            break
    if not obj_asset or obj_asset.get("status") == "deleted":
        out = _err("NOT_FOUND", "Target object not found in local cache", object_type=object_type, object_id=object_id)
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    # Resolve tag asset by name
    tag_asset = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("superset_instance_id") != instance_id:
            continue
        if a.get("asset_type") != "tag":
            continue
        if isinstance(a.get("name"), str) and a.get("name").strip().lower() == tag_name.lower():
            tag_asset = a
            break
    if not tag_asset or tag_asset.get("status") == "deleted":
        out = _err("NOT_FOUND", "Tag not found in local cache", tag_name=tag_name)
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    # Find assignment
    assignment = None
    for ta in assigns:
        if not isinstance(ta, dict):
            continue
        if ta.get("superset_instance_id") != instance_id:
            continue
        if ta.get("tag_asset_id") == tag_asset.get("id") and ta.get("object_asset_id") == obj_asset.get("id") and ta.get("object_type") == object_type:
            assignment = ta
            break

    if not assignment:
        out = _err("NOT_FOUND", "Tag association not found", tag_name=tag_name, object_type=object_type, object_id=object_id)
        _log("error", out["error"]["code"], out["error"]["message"], superset_instance_id=instance_id)
        return out

    now = _now
    # Must be idempotent: if already removed, keep removed and return ok.
    if assignment.get("status") == "active":
        assignment["status"] = "removed"
        assignment["updated_at"] = now
        _save("tag_assignments.json", assigns)
        changed = True
    else:
        # do not claim success without effect? For idempotent remove, success is allowed even when no change.
        assignment["updated_at"] = now
        _save("tag_assignments.json", assigns)
        changed = False

    resp = {
        "result": {
            "tag_name": tag_name,
            "object_type": object_type,
            "object_id": object_id,
            "status": "removed",
        },
        "local_cache": {
            "assignment": {
                "id": assignment.get("id"),
                "changed": changed,
            }
        },
        "superset_instance": {
            "id": instance_id,
            "base_url": instance.get("base_url"),
        },
    }
    _log("ok", superset_instance_id=instance_id, object_type=object_type, object_id=object_id)
    return resp

def superset_explore_form_data_create(form_data, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # No request-log/usage collections declared in schema; nothing to persist for dynamics.

    # Validate input
    if form_data is None or not isinstance(form_data, dict):
        return _err("VALIDATION_ERROR", "form_data is required and must be an object")

    # Resolve an active superset instance deterministically (lowest created_at)
    instances = _load("superset_instances.json")
    active = [r for r in instances if isinstance(r, dict) and r.get("status") == "active"]
    if not active:
        return _err("UNAUTHORIZED", "No active Superset instance is configured")
    def _created_key(r):
        v = r.get("created_at")
        return (v is None, v if isinstance(v, str) else "")
    active.sort(key=_created_key)
    instance = active[0]
    instance_id = instance.get("id")

    # Need a usable authenticated session for Explore APIs
    sessions = _load("auth_sessions.json")
    usable = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("superset_instance_id") != instance_id:
            continue
        if s.get("status") == "authenticated" and s.get("token_type") == "bearer" and s.get("access_token"):
            usable.append(s)
    if not usable:
        return _err("UNAUTHORIZED", "No authenticated Superset session available for Explore APIs")

    # Create a key-based asset (explore_form_data)
    assets = _load("superset_assets.json")

    # Generate unique key deterministically enough
    # (Superset would generate; here we persist locally to enable retrieval.)
    for _ in range(5):
        key = "efd_" + uuid.uuid4().hex
        if not any(isinstance(a, dict) and a.get("superset_instance_id") == instance_id and a.get("asset_type") == "explore_form_data" and a.get("superset_key") == key for a in assets):
            break
    else:
        return _err("CONFLICT", "Could not allocate a unique explore form_data key")

    asset_id = "sa_" + uuid.uuid4().hex
    row = {
        "id": asset_id,
        "superset_instance_id": instance_id,
        "asset_type": "explore_form_data",
        "superset_object_id": None,
        "superset_key": key,
        "name": None,
        "slug": None,
        "database_asset_id": None,
        "dataset_asset_id": None,
        "schema_name": None,
        "table_name": None,
        "datasource_type": None,
        "viz_type": None,
        "payload": {"form_data": form_data},
        "owners": None,
        "status": "active",
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }

    assets.append(row)
    _save("superset_assets.json", assets)

    # Return a vendor-like envelope
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "key": key,
        "asset": row,
        "superset_instance": {
            "id": instance_id,
            "base_url": instance.get("base_url"),
            "api_prefix": instance.get("api_prefix"),
        },
        "meta": {
            "latency_ms": latency_ms,
        },
    }

