def superset_menu_get(**_extra):
    import json, os, datetime, time, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_menu_get"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s:
            return None
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, credential_id=None, superset_instance_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "superset_instance_id": superset_instance_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve an active instance deterministically (lowest created_at) and a usable authenticated session
    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        instances = []
    active = [r for r in instances if isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("base_url"), str) and r.get("base_url").strip()]
    if not active:
        _audit("error", error_code="NOT_FOUND", error_message="No active Superset instance configured.")
        return _err("NOT_FOUND", "No active Superset instance configured.")
    active.sort(key=lambda r: (_parse_iso(r.get("created_at")) or datetime.datetime.max, r.get("id") or ""))
    inst = active[0]

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    usable = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("superset_instance_id") != inst.get("id"):
            continue
        if s.get("status") != "authenticated":
            continue
        if s.get("token_type") != "bearer":
            continue
        tok = s.get("access_token")
        if not isinstance(tok, str) or not tok.strip():
            continue
        usable.append(s)
    if not usable:
        _audit("error", superset_instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No authenticated Superset session available.")
        return _err("UNAUTHORIZED", "No valid Superset authentication is available.")
    # Deterministically pick the most recently updated authenticated session
    usable.sort(key=lambda s: (_parse_iso(s.get("updated_at")) or datetime.datetime.min, s.get("id") or ""), reverse=True)
    sess = usable[0]

    base_url = inst["base_url"].rstrip("/")
    api_prefix = inst.get("api_prefix") or "/api/v1"
    if not isinstance(api_prefix, str) or not api_prefix.startswith("/"):
        api_prefix = "/api/v1"
    url = base_url + api_prefix.rstrip("/") + "/menu/"

    verify_tls = bool(inst.get("verify_tls", True))
    timeout_ms = inst.get("default_timeout_ms")
    if not isinstance(timeout_ms, int) or timeout_ms < 1000 or timeout_ms > 120000:
        timeout_ms = 30000

    headers = {
        "Accept": "application/json",
        "Authorization": "Bearer " + sess["access_token"],
    }

    ctx = None
    if not verify_tls:
        import ssl
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

    try:
        req = urllib.request.Request(url, headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=timeout_ms / 1000.0, context=ctx) as resp:
            status = resp.getcode()
            body = resp.read()
            ctype = resp.headers.get("Content-Type", "")
    except urllib.error.HTTPError as e:
        status = getattr(e, "code", None)
        if status in (401, 403):
            # Update session validation info; on 401/403 treat as expired (best-effort for menu auth failure)
            now = _iso_now()
            auth_sessions = _load("auth_sessions.json")
            if not isinstance(auth_sessions, list):
                auth_sessions = []
            updated = False
            for s in auth_sessions:
                if isinstance(s, dict) and s.get("id") == sess.get("id"):
                    s["last_validated_at"] = now
                    s["last_validation_ok"] = False
                    s["last_error_code"] = str(status)
                    try:
                        emsg = e.read().decode("utf-8", errors="replace")
                    except Exception:
                        emsg = "HTTP error"
                    s["last_error_message"] = emsg[:2000]
                    # Transition to expired if allowed
                    cur = s.get("status")
                    if cur in ("authenticated", "anonymous", "expired", "revoked", "error"):
                        if cur == "authenticated" or cur == "expired" or cur == "error" or cur == "anonymous":
                            s["status"] = "expired"
                    s["access_token_expires_at"] = None
                    s["updated_at"] = now
                    updated = True
                    break
            if updated:
                _save("auth_sessions.json", auth_sessions)
            if status == 401:
                _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="Superset returned 401 for menu.")
                return _err("UNAUTHORIZED", "No valid Superset authentication is available.", upstream_status=401)
            _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="FORBIDDEN", error_message="Superset returned 403 for menu.")
            return _err("FORBIDDEN", "Authenticated user is not permitted to access menu metadata.", upstream_status=403)
        # Other upstream errors
        try:
            b = e.read()
        except Exception:
            b = b""
        msg = None
        try:
            msg = b.decode("utf-8", errors="replace")
        except Exception:
            msg = "Upstream error"
        _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="UPSTREAM_ERROR", error_message=f"HTTP {status}")
        return _err("UPSTREAM_ERROR", "Non-success response from Superset.", upstream_status=status, upstream_body=msg[:4000])
    except urllib.error.URLError as e:
        _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="UPSTREAM_ERROR", error_message=str(e))
        return _err("UPSTREAM_ERROR", "Failed to reach Superset.", upstream_error=str(e))
    except Exception as e:
        _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="UPSTREAM_ERROR", error_message=str(e))
        return _err("UPSTREAM_ERROR", "Unexpected error calling Superset.", details=str(e))

    # Parse JSON
    data = None
    try:
        txt = body.decode("utf-8", errors="replace")
        data = json.loads(txt) if txt.strip() else None
    except Exception:
        _audit("error", credential_id=sess.get("id"), superset_instance_id=inst.get("id"), error_code="UPSTREAM_ERROR", error_message="Invalid JSON from Superset menu.")
        return _err("UPSTREAM_ERROR", "Superset returned invalid JSON.", upstream_status=status, content_type=ctype)

    _audit("ok", credential_id=sess.get("id"), superset_instance_id=inst.get("id"))
    return {
        "superset_instance_id": inst.get("id"),
        "base_url": inst.get("base_url"),
        "menu": data,
        "upstream_status": status,
    }

def superset_config_get_base_url(**_extra):
