def superset_advanced_data_type_convert(type_name, value, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_advanced_data_type_convert"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _pick_active_instance(instances_rows):
        active = [r for r in instances_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))
        return active[0]

    def _pick_authenticated_session(sessions_rows, instance_id):
        candidates = []
        for s in sessions_rows:
            if not isinstance(s, dict):
                continue
            if s.get("superset_instance_id") != instance_id:
                continue
            if not s.get("access_token") or s.get("token_type") != "bearer":
                continue
            candidates.append(s)
        if not candidates:
            return None
        def _score(s):
            st = s.get("status")
            last_ok = bool(s.get("last_validation_ok"))
            last_val = _parse_dt(s.get("last_validated_at"))
            rank = {"authenticated": 0, "expired": 1, "error": 2, "revoked": 3, "anonymous": 4}.get(st, 5)
            return (rank, 0 if last_ok else 1, -(last_val.timestamp() if last_val else -1))
        candidates.sort(key=_score)
        return candidates[0]

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(type_name, str) or not type_name.strip():
        _log("error", error_code="VALIDATION_ERROR", error_message="type_name must be non-empty string")
        return _err("VALIDATION_ERROR", "`type_name` must be a non-empty string.", field="type_name")

    try:
        json.dumps(value)
    except TypeError:
        _log("error", error_code="VALIDATION_ERROR", error_message="value must be JSON-serializable")
        return _err("VALIDATION_ERROR", "`value` must be JSON-serializable.", field="value")

    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    # Auth context (must exist)
    instances = _ensure_list(_load("superset_instances.json"))
    sessions = _ensure_list(_load("auth_sessions.json"))
    inst = _pick_active_instance(instances)
    if not inst:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance is configured.")
    sess = _pick_authenticated_session(sessions, inst.get("id"))
    if not sess:
        _log("error", instance_id=inst.get("id"), error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available for the active Superset instance.")

    # Offline conversion: emulate a subset of Superset advanced data types deterministically.
    tn = type_name.strip().lower()
    known = {
        "string", "str", "text",
        "integer", "int", "bigint",
        "float", "double", "number",
        "boolean", "bool",
        "json",
        "date", "datetime", "timestamp",
        "uuid",
    }
    if tn not in known:
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", error_message="Unknown advanced data type", meta={"type_name": type_name})
        return _err("NOT_FOUND", "Requested advanced data type is not recognized.", type_name=type_name)

    converted = None
    try:
        if tn in ("string", "str", "text"):
            converted = "" if value is None else str(value)
        elif tn in ("integer", "int", "bigint"):
            if value is None or (isinstance(value, str) and not value.strip()):
                raise ValueError("empty")
            converted = int(value)
        elif tn in ("float", "double", "number"):
            if value is None or (isinstance(value, str) and not value.strip()):
                raise ValueError("empty")
            converted = float(value)
        elif tn in ("boolean", "bool"):
            if isinstance(value, bool):
                converted = value
            elif isinstance(value, (int, float)) and value in (0, 1):
                converted = bool(value)
            elif isinstance(value, str):
                v = value.strip().lower()
                if v in ("true", "t", "1", "yes", "y", "on"):
                    converted = True
                elif v in ("false", "f", "0", "no", "n", "off"):
                    converted = False
                else:
                    raise ValueError("invalid boolean")
            else:
                raise ValueError("invalid boolean")
        elif tn == "json":
            # If already JSON-compatible, pass through. If string, attempt parse.
            if isinstance(value, str):
                s = value.strip()
                if s.startswith("{") or s.startswith("[") or s in ("null", "true", "false") or (s and (s[0].isdigit() or s[0] == "-")):
                    converted = json.loads(value)
                else:
                    converted = value
            else:
                converted = value
        elif tn in ("date",):
            if isinstance(value, str):
                d = datetime.date.fromisoformat(value.strip())
                converted = d.isoformat()
            elif isinstance(value, datetime.date) and not isinstance(value, datetime.datetime):
                converted = value.isoformat()
            else:
                raise ValueError("invalid date")
        elif tn in ("datetime", "timestamp"):
            if isinstance(value, str):
                dt = _parse_dt(value.strip())
                if not dt:
                    dt = datetime.datetime.fromisoformat(value.strip())
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                converted = dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            elif isinstance(value, datetime.datetime):
                dt = value
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                converted = dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            else:
                raise ValueError("invalid datetime")
        elif tn == "uuid":
            if isinstance(value, str):
                u = uuid.UUID(value.strip())
                converted = str(u)
            else:
                raise ValueError("invalid uuid")
    except Exception:
        _log("error", instance_id=inst.get("id"), session_id=sess.get("id"), error_code="VALIDATION_ERROR", error_message="Conversion failed", meta={"type_name": type_name})
        return _err("VALIDATION_ERROR", "Value could not be converted to the requested type.", type_name=type_name)

    _log("ok", instance_id=inst.get("id"), session_id=sess.get("id"), meta={"type_name": type_name})
    return {"type_name": type_name, "value": value, "converted": converted}

def superset_advanced_data_type_list(refresh=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
