    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_advanced_data_type_list"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, instance_id=None, session_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log("error", error_code="VALIDATION_ERROR", error_message="refresh must be boolean")
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    # rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list) and logs:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-4000:]:
            ts = _parse_dt((r or {}).get("timestamp") or (r or {}).get("created_at"))
            if ts and ts.replace(tzinfo=None) >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT", error_message="global_120_per_min")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit="120/min")

    instances = _load("superset_instances.json")
    sessions = _load("auth_sessions.json")
    if not isinstance(instances, list) or not isinstance(sessions, list):
        _log("error", error_code="CONFLICT", error_message="Datastore invalid")
        return _err("CONFLICT", "Failed to read datastore.")

    active_instances = [i for i in instances if isinstance(i, dict) and i.get("status") == "active" and i.get("id")]
    if not active_instances:
        _log("error", error_code="UNAUTHORIZED", error_message="No active Superset instance configured")
        return _err("UNAUTHORIZED", "No active Superset instance configured.")

    active_instances.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))

    chosen_inst = None
    chosen_sess = None
    for inst in active_instances:
        iid = inst["id"]
        sess_cand = [s for s in sessions if isinstance(s, dict) and s.get("superset_instance_id") == iid and s.get("access_token") and s.get("status") == "authenticated"]
        if sess_cand:
            sess_cand.sort(key=lambda s: (_parse_dt(s.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), s.get("id") or ""))
            chosen_inst, chosen_sess = inst, sess_cand[0]
            break

    if not chosen_inst or not chosen_sess:
        _log("error", error_code="UNAUTHORIZED", error_message="No valid Superset session/token available")
        return _err("UNAUTHORIZED", "No valid Superset session/token is available.")

    # optional cache file
    cache_file = "advanced_data_types_cache.json"
    cache = _load(cache_file)
    if not isinstance(cache, dict):
        cache = {}

    iid = chosen_inst["id"]
    now = _now_iso()

    if (not refresh) and isinstance(cache.get(iid), dict) and isinstance(cache[iid].get("types"), list):
        _log("ok", instance_id=iid, session_id=chosen_sess.get("id"))
        return {"types": cache[iid]["types"], "cached": True, "superset_instance_id": iid, "fetched_at": cache[iid].get("fetched_at")}

    # Offline: return a deterministic list (common Superset advanced data types)
    types = [
        {"name": "string"},
        {"name": "integer"},
        {"name": "float"},
        {"name": "boolean"},
        {"name": "json"},
        {"name": "date"},
        {"name": "datetime"},
    ]
    cache[iid] = {"types": types, "fetched_at": now}
    _save(cache_file, cache)

    _log("ok", instance_id=iid, session_id=chosen_sess.get("id"))
    return {"types": types, "cached": False, "superset_instance_id": iid, "fetched_at": now}

def superset_instance_list(status=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
