            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Basic "request log" if present (best-effort, schema not provided)
    def _log(status_code, endpoint, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": status_code,
                "detail": detail,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)

    # Validate inputs
    if status is not None and status not in ("active", "disabled"):
        _log("VALIDATION_ERROR", "superset_instance_list", "bad status")
        return _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'disabled'.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        _log("VALIDATION_ERROR", "superset_instance_list", "bad page")
        return _err("VALIDATION_ERROR", "Invalid page. Must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("VALIDATION_ERROR", "superset_instance_list", "bad page_size")
        return _err("VALIDATION_ERROR", "Invalid page_size. Must be an integer between 1 and 200.")

    # Ambient auth: if there is any explicit RBAC collection, enforce it; otherwise allow.
    # The tool description mentions FORBIDDEN; no schema is provided to implement fine-grained checks.
    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        _log("VALIDATION_ERROR", "superset_instance_list", "datastore corrupt")
        return _err("VALIDATION_ERROR", "Datastore is invalid for superset_instances.")

    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1]
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    # Filter
    rows = instances
    if status is not None:
        rows = [r for r in rows if isinstance(r, dict) and r.get("status") == status]
    else:
        rows = [r for r in rows if isinstance(r, dict)]

    # Deterministic order: oldest created first (fallback to id)
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        return (dt or datetime.datetime.min, r.get("id") or "")
    rows.sort(key=_sort_key)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    _log("OK", "superset_instance_list", f"returned={len(page_rows)} total={total}")
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        }
    }

def superset_instance_update(id, display_name=None, base_url=None, api_prefix=None, verify_tls=None, default_timeout_ms=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _log(status_code, endpoint, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": status_code,
                "detail": detail,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)

    # Validate id
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", "superset_instance_update", "bad id")
        return _err("VALIDATION_ERROR", "Invalid id. Must be a non-empty string.")

    # Validate optional fields types/enums/ranges
    if display_name is not None and not isinstance(display_name, str):
        _log("VALIDATION_ERROR", "superset_instance_update", "bad display_name type")
        return _err("VALIDATION_ERROR", "display_name must be a string or null.")
    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.strip():
            _log("VALIDATION_ERROR", "superset_instance_update", "bad base_url")
            return _err("VALIDATION_ERROR", "base_url must be a non-empty string or null.")
        # very light URL sanity
        if not re.match(r"^https?://", base_url.strip()):
            _log("VALIDATION_ERROR", "superset_instance_update", "base_url missing scheme")
            return _err("VALIDATION_ERROR", "base_url must start with http:// or https://.")
        base_url = base_url.strip().rstrip("/")
    if api_prefix is not None:
        if not isinstance(api_prefix, str) or not api_prefix.strip():
            _log("VALIDATION_ERROR", "superset_instance_update", "bad api_prefix")
            return _err("VALIDATION_ERROR", "api_prefix must be a non-empty string or null.")
        api_prefix = api_prefix.strip()
        if not api_prefix.startswith("/"):
            api_prefix = "/" + api_prefix
    if verify_tls is not None and not isinstance(verify_tls, bool):
        _log("VALIDATION_ERROR", "superset_instance_update", "bad verify_tls")
        return _err("VALIDATION_ERROR", "verify_tls must be a boolean or null.")
    if default_timeout_ms is not None:
        if not isinstance(default_timeout_ms, int) or default_timeout_ms < 1:
            _log("VALIDATION_ERROR", "superset_instance_update", "bad default_timeout_ms")
            return _err("VALIDATION_ERROR", "default_timeout_ms must be an integer >= 1 or null.")
        # Schema constraint: BETWEEN 1000 AND 120000
        if default_timeout_ms < 1000 or default_timeout_ms > 120000:
            _log("VALIDATION_ERROR", "superset_instance_update", "default_timeout_ms range")
            return _err("VALIDATION_ERROR", "default_timeout_ms must be between 1000 and 120000 milliseconds.")
    if status is not None and status not in ("active", "disabled"):
        _log("VALIDATION_ERROR", "superset_instance_update", "bad status")
        return _err("VALIDATION_ERROR", "status must be 'active', 'disabled', or null.")

    # Require non-empty payload (at least one field not None)
    if all(v is None for v in (display_name, base_url, api_prefix, verify_tls, default_timeout_ms, status)):
        _log("VALIDATION_ERROR", "superset_instance_update", "empty payload")
        return _err("VALIDATION_ERROR", "Empty payload. Provide at least one field to update.")

    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        _log("VALIDATION_ERROR", "superset_instance_update", "datastore corrupt")
        return _err("VALIDATION_ERROR", "Datastore is invalid for superset_instances.")

    idx = None
    for i, r in enumerate(instances):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("NOT_FOUND", "superset_instance_update", f"id={id}")
        return _err("NOT_FOUND", "Superset instance not found.", id=id)

    inst = instances[idx]

    # Enforce unique(base_url)
    if base_url is not None:
        for r in instances:
            if isinstance(r, dict) and r.get("id") != id and r.get("base_url") == base_url:
                _log("CONFLICT", "superset_instance_update", "base_url unique violation")
                return _err("CONFLICT", "base_url must be unique among instances.", base_url=base_url)

    # Lifecycle transitions
    transitions = {"active": ["disabled"], "disabled": ["active"]}
    if status is not None:
        cur = inst.get("status")
        if cur not in transitions:
            _log("VALIDATION_ERROR", "superset_instance_update", "unknown current status")
            return _err("VALIDATION_ERROR", "Instance has invalid current status.", current_status=cur)
        if status != cur and status not in transitions.get(cur, []):
            _log("INVALID_TRANSITION", "superset_instance_update", f"{cur}->{status}")
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)

        # CONFLICT rule: do not allow multiple active instances (tool surface has no selection)
        if status == "active":
            active_others = [r for r in instances if isinstance(r, dict) and r.get("id") != id and r.get("status") == "active"]
            if active_others:
                _log("CONFLICT", "superset_instance_update", "multiple active instances not supported")
                return _err("CONFLICT", "Enabling this instance would result in multiple active instances, which is not supported.",
                            active_instance_ids=[r.get("id") for r in active_others])

    # Apply updates
    now = datetime.datetime.utcnow().isoformat() + "Z"
    if display_name is not None:
        inst["display_name"] = display_name
    if base_url is not None:
        inst["base_url"] = base_url
    if api_prefix is not None:
        inst["api_prefix"] = api_prefix
    if verify_tls is not None:
        inst["verify_tls"] = verify_tls
    if default_timeout_ms is not None:
        inst["default_timeout_ms"] = default_timeout_ms
    if status is not None:
        inst["status"] = status
    inst["updated_at"] = now

    instances[idx] = inst
    _save("superset_instances.json", instances)

    _log("OK", "superset_instance_update", f"id={id}")
    return {"data": inst}

def superset_auth_session_create(superset_instance_id, username=None, password=None, provider=None, refresh=None, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _log(status_code, endpoint, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": status_code,
                "detail": detail,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)

    if provider is None:
        provider = "db"
    if refresh is None:
        refresh = True

    # Validate inputs
    if not isinstance(superset_instance_id, str) or not superset_instance_id.strip():
        _log("VALIDATION_ERROR", "superset_auth_session_create", "bad superset_instance_id")
        return _err("VALIDATION_ERROR", "superset_instance_id must be a non-empty string.")
    if provider != "db":
        _log("VALIDATION_ERROR", "superset_auth_session_create", "bad provider")
        return _err("VALIDATION_ERROR", "provider must be 'db'.")
    if not isinstance(refresh, bool):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "bad refresh")
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")
    if username is not None and not isinstance(username, str):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "bad username type")
        return _err("VALIDATION_ERROR", "username must be a string or null.")
    if password is not None and not isinstance(password, str):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "bad password type")
        return _err("VALIDATION_ERROR", "password must be a string or null.")
    if username is not None and (password is None or password == ""):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "password required")
        return _err("VALIDATION_ERROR", "password is required when username is provided.")

    instances = _load("superset_instances.json")
    if not isinstance(instances, list):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "datastore corrupt instances")
        return _err("VALIDATION_ERROR", "Datastore is invalid for superset_instances.")
    instance = next((r for r in instances if isinstance(r, dict) and r.get("id") == superset_instance_id), None)
    if not instance:
        _log("NOT_FOUND", "superset_auth_session_create", f"instance={superset_instance_id}")
        return _err("NOT_FOUND", "Superset instance not found.", superset_instance_id=superset_instance_id)

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        _log("VALIDATION_ERROR", "superset_auth_session_create", "datastore corrupt sessions")
        return _err("VALIDATION_ERROR", "Datastore is invalid for auth_sessions.")

    # Reuse existing session by (instance, username) when username not null; else reuse anonymous per instance if present
    sess = None
    sess_idx = None
    if username is not None:
        for i, r in enumerate(sessions):
            if isinstance(r, dict) and r.get("superset_instance_id") == superset_instance_id and r.get("username") == username:
                sess = r
                sess_idx = i
                break
    else:
        # anonymous session: reuse an existing anonymous session for instance with username null if present
        for i, r in enumerate(sessions):
            if isinstance(r, dict) and r.get("superset_instance_id") == superset_instance_id and r.get("username") is None:
                sess = r
                sess_idx = i
                break

    now = datetime.datetime.utcnow().isoformat() + "Z"

    def _transition_allowed(cur, nxt):
        transitions = {
            "anonymous": ["authenticated", "error"],
            "authenticated": ["expired", "revoked", "error"],
            "expired": ["authenticated", "revoked", "error"],
            "revoked": ["authenticated"],
            "error": ["anonymous", "authenticated"],
        }
        return cur == nxt or (cur in transitions and nxt in transitions[cur])

    def _set_status(s, new_status):
        cur = s.get("status")
        if cur is None:
            cur = "anonymous"
            s["status"] = cur
        if not _transition_allowed(cur, new_status):
            return False, cur
        if cur != new_status:
            s["status"] = new_status
        return True, cur

    # Create session if none
    if sess is None:
        sess = {
            "id": f"as_{secrets.token_hex(12)}",
            "superset_instance_id": superset_instance_id,
            "username": username if username is not None else None,
            "access_token": None,
            "refresh_token": None,
            "token_type": "bearer",
            "access_token_expires_at": None,
            "last_validated_at": None,
            "last_validation_ok": False,
            "last_error_code": None,
            "last_error_message": None,
            "status": "anonymous",
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
        sess_idx = len(sessions) - 1

    # If caller provided username but we reused a session, never overwrite non-null username with null (rule)
    if username is not None and sess.get("username") is None:
        sess["username"] = username

    # Offline "Superset auth": no real HTTP. We simulate flows using stored tokens.
    # If username omitted -> anonymous session (do not authenticate)
    if username is None:
        sess["updated_at"] = now
        sessions[sess_idx] = sess
        _save("auth_sessions.json", sessions)
        _log("OK", "superset_auth_session_create", f"anonymous session id={sess.get('id')}")
        return {"data": sess}

    # username provided: attempt validate/refresh/login per business rules
    # 1) validate existing access_token if refresh=true
    if refresh and sess.get("access_token"):
        sess["last_validated_at"] = now
        # Without remote call, we consider token valid if session is authenticated and not expired/revoked
        if sess.get("status") == "authenticated":
            sess["last_validation_ok"] = True
            sess["last_error_code"] = None
            sess["last_error_message"] = None
        else:
            # treat as invalid (mimic /me 401/403 => expired)
            sess["last_validation_ok"] = False
            sess["last_error_code"] = "401"
            sess["last_error_message"] = "Token not valid for current session status."
            ok, cur = _set_status(sess, "expired")
            if not ok:
                # If cannot transition, mark error
                _set_status(sess, "error")
            sess["access_token_expires_at"] = None

        if sess.get("last_validation_ok"):
            sess["updated_at"] = now
            sessions[sess_idx] = sess
            _save("auth_sessions.json", sessions)
            _log("OK", "superset_auth_session_create", f"validated existing token id={sess.get('id')}")
            return {"data": sess}

    # 2) refresh if possible and refresh=true
    if refresh and sess.get("refresh_token"):
        # Simulate refresh success: rotate tokens
        sess["access_token"] = "at_" + secrets.token_urlsafe(24)
        sess["refresh_token"] = "rt_" + secrets.token_urlsafe(24)
        sess["token_type"] = "bearer"
        sess["access_token_expires_at"] = None
        sess["last_validated_at"] = now
        sess["last_validation_ok"] = True
        sess["last_error_code"] = None
        sess["last_error_message"] = None
        ok, cur = _set_status(sess, "authenticated")
        if not ok:
            _log("INVALID_TRANSITION", "superset_auth_session_create", f"{cur}->authenticated")
            return _err("INVALID_TRANSITION", "Illegal status transition to authenticated.", from_status=cur, to_status="authenticated")
        sess["updated_at"] = now
        sessions[sess_idx] = sess
        _save("auth_sessions.json", sessions)
        _log("OK", "superset_auth_session_create", f"refreshed token id={sess.get('id')}")
        return {"data": sess}

    # 3) login using username/password (offline: accept any non-empty password)
    if not password:
        _log("UNAUTHORIZED", "superset_auth_session_create", "missing password for login")
        return _err("UNAUTHORIZED", "Superset rejected credentials (password missing).")

    # Success: set tokens and authenticated
    sess["access_token"] = "at_" + secrets.token_urlsafe(24)
    # Some deployments may not return refresh_token; we set one to enable refresh flows locally
    sess["refresh_token"] = sess.get("refresh_token") or ("rt_" + secrets.token_urlsafe(24))
    sess["token_type"] = "bearer"
    sess["access_token_expires_at"] = None
    sess["last_validated_at"] = now
    sess["last_validation_ok"] = True
    sess["last_error_code"] = None
    sess["last_error_message"] = None
    ok, cur = _set_status(sess, "authenticated")
    if not ok:
        _log("INVALID_TRANSITION", "superset_auth_session_create", f"{cur}->authenticated")
        return _err("INVALID_TRANSITION", "Illegal status transition to authenticated.", from_status=cur, to_status="authenticated")
    sess["updated_at"] = now

    # Enforce unique(superset_instance_id, username) where username not null
    if sess.get("username") is not None:
        for r in sessions:
            if r is sess:
                continue
            if isinstance(r, dict) and r.get("superset_instance_id") == superset_instance_id and r.get("username") == sess.get("username") and r.get("id") != sess.get("id"):
                _log("CONFLICT", "superset_auth_session_create", "unique(instance,username) violation")
                return _err("CONFLICT", "An auth session already exists for this instance and username.",
                            superset_instance_id=superset_instance_id, username=sess.get("username"))

    sessions[sess_idx] = sess
    _save("auth_sessions.json", sessions)
    _log("OK", "superset_auth_session_create", f"logged in id={sess.get('id')}")
    return {"data": sess}

def superset_auth_session_update(id, status=None, revoke_remote=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0123000" if __import__("os").path.isdir("./environment_mix/0123000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "superset_auth_session_update"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_list(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _log(status_s, session_id=None, instance_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        logs = logs if isinstance(logs, list) else []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "superset_integration",
            "endpoint": endpoint,
            "status": status_s,
            "superset_instance_id": instance_id,
            "auth_session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if revoke_remote is None:
        revoke_remote = False
    if not isinstance(revoke_remote, bool):
        _log("error", session_id=id if isinstance(id, str) else None, error_code="VALIDATION_ERROR", error_message="revoke_remote must be boolean")
        return _err("VALIDATION_ERROR", "`revoke_remote` must be a boolean.", field="revoke_remote")

    if not isinstance(id, str) or not id.strip():
        _log("error", error_code="VALIDATION_ERROR", error_message="id must be non-empty string")
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.", field="id")

    allowed_status = ("anonymous", "authenticated", "expired", "revoked", "error")
    if status is not None and status not in allowed_status:
        _log("error", session_id=id, error_code="VALIDATION_ERROR", error_message="invalid status")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=list(allowed_status))

    # Rate limit: best-effort global 120/min
    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs0[-5000:]:
            ts = _parse_dt((r or {}).get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log("error", session_id=id, error_code="RATE_LIMIT", error_message="Too many requests")
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=120)

    sessions = _ensure_list(_load("auth_sessions.json"))
    instances = _ensure_list(_load("superset_instances.json"))

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("error", session_id=id, error_code="NOT_FOUND", error_message="Auth session not found")
        return _err("NOT_FOUND", "Auth session not found.", id=id)

    sess = sessions[idx]
    inst_id = sess.get("superset_instance_id")

    # Validate instance reference exists
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == inst_id:
            inst = r
            break
    if not inst:
        _log("error", session_id=id, instance_id=inst_id, error_code="NOT_FOUND", error_message="Superset instance not found for session")
        return _err("NOT_FOUND", "Superset instance referenced by session was not found.", superset_instance_id=inst_id)

    # Lifecycle transitions
    transitions = {
        "anonymous": set(["authenticated", "error"]),
        "authenticated": set(["expired", "revoked", "error"]),
        "expired": set(["authenticated", "revoked", "error"]),
        "revoked": set(["authenticated"]),
        "error": set(["anonymous", "authenticated"]),
    }

    now = _now_iso()
    cur = sess.get("status")
    if status is not None and status != cur:
        if cur not in transitions or status not in transitions[cur]:
            _log("error", session_id=id, instance_id=inst_id, error_code="INVALID_TRANSITION", error_message="Invalid session status transition", meta={"from": cur, "to": status})
            return _err("INVALID_TRANSITION", "Invalid auth session status transition.", from_status=cur, to_status=status)

        # Apply state-specific side effects
        if status == "anonymous":
            # Clear auth-related fields, but keep username if present (never overwrite non-null username with null)
            sess["access_token"] = None
            sess["refresh_token"] = None
            sess["access_token_expires_at"] = None
            sess["last_validation_ok"] = False
            sess["last_error_code"] = None
            sess["last_error_message"] = None
        elif status == "revoked":
            # best-effort remote revoke: offline cannot call Superset, but reflect intent
            sess["access_token"] = None if revoke_remote else sess.get("access_token")
            sess["refresh_token"] = None if revoke_remote else sess.get("refresh_token")
            sess["access_token_expires_at"] = None
            sess["last_validation_ok"] = False
            if revoke_remote:
                sess["last_error_code"] = None
                sess["last_error_message"] = None
        elif status == "expired":
            sess["access_token_expires_at"] = None
            sess["last_validation_ok"] = False

        sess["status"] = status
        sess["updated_at"] = now
        sessions[idx] = sess
        _save("auth_sessions.json", sessions)

    _log("ok", session_id=id, instance_id=inst_id, meta={"updated": status is not None and status != cur, "revoke_remote": revoke_remote})
    return {"auth_session": sess}
